const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, LevelFormat, BorderStyle
} = require('docx');
const fs = require('fs');

const FONT = "Arial";
const BLUE = "2E5FA3";
const DARK = "1A1A1A";
const MID  = "444444";
const RULE_COLOR = "CCCCCC";

function rule() {
  return new Paragraph({
    children: [],
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: RULE_COLOR, space: 1 } },
    spacing: { before: 80, after: 160 }
  });
}

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, font: FONT, size: 36, bold: true, color: BLUE })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, font: FONT, size: 26, bold: true, color: DARK })]
  });
}

function h3(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_3,
    children: [new TextRun({ text, font: FONT, size: 22, bold: true, color: MID })]
  });
}

function para(runs, opts = {}) {
  const children = (typeof runs === 'string')
    ? [new TextRun({ text: runs, font: FONT, size: 22, color: DARK })]
    : runs;
  return new Paragraph({ children, spacing: { before: 80, after: 120 }, ...opts });
}

function bold(text, color = DARK) {
  return new TextRun({ text, font: FONT, size: 22, bold: true, color });
}

function normal(text) {
  return new TextRun({ text, font: FONT, size: 22, color: DARK });
}

function italic(text) {
  return new TextRun({ text, font: FONT, size: 22, italics: true, color: MID });
}

function bullet(text, numbRef = "bullets") {
  const children = (typeof text === 'string')
    ? [new TextRun({ text, font: FONT, size: 22, color: DARK })]
    : text;
  return new Paragraph({
    numbering: { reference: numbRef, level: 0 },
    children,
    spacing: { before: 60, after: 60 }
  });
}

function blockquote(text) {
  return new Paragraph({
    children: [new TextRun({ text, font: FONT, size: 22, italics: true, color: "555555" })],
    indent: { left: 720 },
    border: { left: { style: BorderStyle.SINGLE, size: 12, color: BLUE, space: 10 } },
    spacing: { before: 120, after: 120 }
  });
}

function spacer(pts = 120) {
  return new Paragraph({ children: [], spacing: { before: 0, after: pts } });
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: FONT, size: 22 } } },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: FONT, color: BLUE },
        paragraph: { spacing: { before: 360, after: 160 }, outlineLevel: 0 }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: FONT, color: DARK },
        paragraph: { spacing: { before: 280, after: 120 }, outlineLevel: 1 }
      },
      {
        id: "Heading3", name: "Heading 3", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 22, bold: true, font: FONT, color: MID },
        paragraph: { spacing: { before: 200, after: 80 }, outlineLevel: 2 }
      }
    ]
  },
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      },
      {
        reference: "numbers",
        levels: [{
          level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [

      // Title
      new Paragraph({
        children: [new TextRun({ text: "chevron::process::AppProcess", font: "Courier New", size: 40, bold: true, color: BLUE })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Class Design Description", font: FONT, size: 26, color: MID, italics: true })],
        spacing: { before: 0, after: 60 }
      }),
      rule(),
      spacer(80),

      // What AppProcess IS
      h1("What AppProcess Is"),
      para([
        normal("AppProcess is the "),
        bold("process-level coordinator"),
        normal(" that owns and decides "),
        italic("when"),
        normal(" the GUI runtime exists and "),
        italic("in what order"),
        normal(" the application moves through its lifetime.")
      ]),
      spacer(80),
      para([bold("It is the conductor, not a musician.")]),
      spacer(80),
      para([bold("It is not:")]),
      bullet("A GUI object"),
      bullet("A window object"),
      bullet("A dispatcher"),
      bullet("A service locator"),
      spacer(160),
      rule(),

      // What problem it solves
      h1("What Problem AppProcess Is Solving"),
      para("Without AppProcess, users would have to:"),
      bullet("Manually sequence GUI backend startup"),
      bullet("Manually handle error paths"),
      bullet("Manually ensure shutdown correctness"),
      bullet([normal("Manually guarantee invariants such as "), italic('"you cannot start twice"'), normal(" and "), italic('"you cannot shutdown before start"')]),
      spacer(120),
      para("Chevron's core promise is:"),
      blockquote("\u201CIf the application is running, it is running correctly.\u201D"),
      para("AppProcess is the class that enforces that promise."),
      spacer(160),
      rule(),

      // Core responsibilities
      h1("Core Responsibilities (Non-Negotiable)"),
      para("AppProcess has exactly three responsibilities:"),
      spacer(80),
      bullet([bold("1.  "), normal("Own the application lifecycle")], "numbers"),
      bullet([bold("2.  "), normal("Own exactly one active GUI engine")], "numbers"),
      bullet([bold("3.  "), normal("Enforce valid sequencing")], "numbers"),
      spacer(120),
      para([italic("Nothing else. If a responsibility does not clearly fit into one of those buckets, it does not belong here.")]),
      spacer(160),
      rule(),

      // Lifetime
      h1("Lifetime of AppProcess"),
      bullet("Constructed near the entry point (user discretion)"),
      bullet("Lives for the entire process"),
      bullet("Destroyed at process exit"),
      spacer(80),
      para([normal("There should be "), bold("one instance per process"), normal(". The mechanism for enforcing this constraint is an open question — candidates include deleted copy/move constructors with documentation, or a runtime assertion on construction. This is deferred pending broader decisions on library-wide enforcement patterns.")]),
      spacer(160),
      rule(),

      // Interaction with GUIEngine
      h1("How AppProcess Interacts With a GUI Engine"),
      para([
        normal("AppProcess holds and drives exactly one "),
        bold("GUIEngine"),
        normal(" instance — the polymorphic interface contract between AppProcess and all concrete GUI backend implementations. AppProcess interacts with the engine exclusively through this interface and has no knowledge of the underlying framework.")
      ]),
      spacer(120),

      h2("1. Committing a Backend"),
      para("This is the first meaningful interaction."),
      spacer(60),
      para("Conceptually:"),
      bullet([normal("User constructs a concrete engine (e.g. "), bold("chevron::wx::Engine"), normal(")")]),
      bullet("User hands ownership to AppProcess"),
      bullet([normal("From this moment on, "), bold("AppProcess owns it")]),
      spacer(80),
      para([bold("Important rules:")]),
      bullet("Only one engine may ever be committed"),
      bullet("Committing twice is an error"),
      bullet("Committing after initialization is an error"),
      spacer(80),
      para([italic("This step is about intent, not GUI initialization. No GUI work occurs here.")]),
      spacer(120),

      h2("2. Initializing the Backend"),
      para("This is where GUI involvement begins."),
      spacer(60),
      para("At this point:"),
      bullet("The backend is selected"),
      bullet("Configuration is locked"),
      bullet("No windows exist yet"),
      spacer(80),
      para("AppProcess instructs the engine:"),
      blockquote("\u201COkay, engine \u2014 initialize yourself, but do not enter the mainloop yet.\u201D"),
      para("This gives the engine a chance to:"),
      bullet("Initialize the GUI library"),
      bullet("Validate environment assumptions"),
      bullet("Prepare internal subsystems"),
      spacer(80),
      para("If this fails:"),
      bullet("No mainloop starts"),
      bullet("No windows are created"),
      bullet("The application can still exit cleanly"),
      spacer(120),

      h2("3. Starting the Runtime (The Mainloop)"),
      para([bold("This is the point of no return.")]),
      spacer(80),
      para("When startRuntime() is called:"),
      bullet("The GUI engine becomes active"),
      bullet("Windows are materialized"),
      bullet("The mainloop begins"),
      bullet("Control flow is given to the GUI framework"),
      bullet("The call blocks until shutdown"),
      spacer(80),
      para("From AppProcess's perspective:"),
      bullet("This is a single operation"),
      bullet("It either returns normally"),
      bullet("Or returns an error code"),
      spacer(80),
      para([italic("AppProcess does not care how the mainloop works. That is the engine's job.")]),
      spacer(120),

      h2("4. Shutdown"),
      para([italic("Shutdown is not the inverse of startup.")]),
      spacer(80),
      para("Key idea:"),
      blockquote("Shutdown may be requested by either user code or the GUI engine."),
      para("So AppProcess must support:"),
      bullet("Explicit shutdown calls from user code"),
      bullet("Implicit shutdown after the mainloop exits"),
      spacer(80),
      para("During shutdown:"),
      bullet("No new GUI work is allowed"),
      bullet("The engine is asked to tear down cleanly"),
      bullet("Resources unwind in a controlled order"),
      spacer(80),
      para([bold("Calling shutdown twice must be safe.")]),
      spacer(160),
      rule(),

      // What AppProcess does NOT know
      h1("What AppProcess Deliberately Does Not Know"),
      para([italic("This is just as important as what it does know.")]),
      spacer(80),
      para("AppProcess does not know:"),
      bullet("What windows exist"),
      bullet("What GUI framework is in use"),
      bullet("How window dispatching works"),
      bullet("How widgets are constructed"),
      bullet("How events are routed"),
      bullet("How window registration is managed (this responsibility belongs to the GUIEngine)"),
      spacer(80),
      para("It only knows:"),
      bullet([italic('"an engine exists"')]),
      bullet([italic('"it is initialized"')]),
      bullet([italic('"it is running"')]),
      bullet([italic('"it is shutting down"')]),
      spacer(160),
      rule(),

      // Error handling
      h1("Error Handling Philosophy"),
      para("AppProcess should:"),
      bullet("Fail fast on misuse"),
      bullet("Return explicit status codes where applicable"),
      bullet("Never leave the system half-alive"),
      bullet("Throw on exceptional code paths"),
      spacer(80),
      para([
        bold("Note: "),
        normal("The precise boundary between returned error codes and thrown exceptions is an open question pending broader library-wide decisions on error handling strategy. The intent above captures the directional philosophy only.")
      ]),
      spacer(80),
      para("Examples of misuse that must be caught:"),
      bullet("Starting without a committed engine"),
      bullet("Committing after start"),
      bullet("Initializing twice"),
      bullet("Runtime configuration errors"),
      spacer(160),
      rule(),

      // Public API shape
      h1("Public API Shape (Conceptual, Not Code)"),
      para("Without syntax, here is what the surface feels like:"),
      spacer(80),
      bullet("Construct an AppProcess"),
      bullet("Commit a configured GUIEngine"),
      bullet("Initialize it"),
      bullet("Start its mainloop"),
      bullet("Gracefully shut it down"),
      spacer(80),
      para([bold("Each step is explicit. No magic. No hidden behavior.")]),
      spacer(160),
      rule(),

      // Open Questions
      h1("Open Questions and Deferred Decisions"),
      para("The following are known open questions that are intentionally deferred:"),
      spacer(80),
      bullet([
        bold("One-instance-per-process enforcement: "),
        normal("The mechanism for enforcing this constraint has not been decided. Candidates include deleted copy/move constructors with documentation, or a runtime assertion on construction.")
      ]),
      bullet([
        bold("Error handling boundary: "),
        normal("The exact line between returned error codes and thrown exceptions is not yet drawn. This depends on broader library-wide error handling strategy decisions.")
      ]),
      bullet([
        bold("Window registration: "),
        normal("AppProcess deliberately has no knowledge of windows. Window registration belongs to the GUIEngine. The mechanics of that registration are deferred to GUIEngine design work.")
      ]),
      bullet([
        bold("GUIEngine interface shape: "),
        normal("The precise set of virtual methods that compose the GUIEngine contract has not yet been defined. This is the next design surface to formalize.")
      ]),
      spacer(160),
      rule(),

      // Footer note
      new Paragraph({
        children: [new TextRun({ text: "Chevron Library \u2014 Internal Design Documentation", font: FONT, size: 18, color: "AAAAAA", italics: true })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 160 }
      })
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/mnt/user-data/outputs/AppProcess_Class_Description.docx', buffer);
  console.log('Done');
});

