const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, LevelFormat, BorderStyle
} = require('docx');
const fs = require('fs');

const FONT = "Arial";
const BLUE = "2E5FA3";
const DARK = "1A1A1A";
const MID  = "444444";
const RULE_COLOR = "CCCCCC";

function rule() {
  return new Paragraph({
    children: [],
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: RULE_COLOR, space: 1 } },
    spacing: { before: 80, after: 160 }
  });
}

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, font: FONT, size: 36, bold: true, color: BLUE })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, font: FONT, size: 26, bold: true, color: DARK })]
  });
}

function para(runs, opts = {}) {
  const children = (typeof runs === 'string')
    ? [new TextRun({ text: runs, font: FONT, size: 22, color: DARK })]
    : runs;
  return new Paragraph({ children, spacing: { before: 80, after: 120 }, ...opts });
}

function bold(text, color = DARK) {
  return new TextRun({ text, font: FONT, size: 22, bold: true, color });
}

function normal(text) {
  return new TextRun({ text, font: FONT, size: 22, color: DARK });
}

function italic(text, color = MID) {
  return new TextRun({ text, font: FONT, size: 22, italics: true, color });
}

function mono(text) {
  return new TextRun({ text, font: "Courier New", size: 20, color: DARK });
}

function bullet(content, ref = "bullets") {
  const children = (typeof content === 'string')
    ? [new TextRun({ text: content, font: FONT, size: 22, color: DARK })]
    : content;
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    children,
    spacing: { before: 60, after: 60 }
  });
}

function blockquote(text) {
  return new Paragraph({
    children: [new TextRun({ text, font: FONT, size: 22, italics: true, color: "555555" })],
    indent: { left: 720 },
    border: { left: { style: BorderStyle.SINGLE, size: 12, color: BLUE, space: 10 } },
    spacing: { before: 120, after: 120 }
  });
}

function spacer(pts = 120) {
  return new Paragraph({ children: [], spacing: { before: 0, after: pts } });
}

function codeBlock(lines) {
  return lines.map((line, i) => new Paragraph({
    children: [new TextRun({ text: line, font: "Courier New", size: 20, color: "2E5FA3" })],
    spacing: { before: i === 0 ? 100 : 0, after: i === lines.length - 1 ? 100 : 0 },
    indent: { left: 720 },
    shading: { fill: "F4F4F4" }
  }));
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: FONT, size: 22 } } },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: FONT, color: BLUE },
        paragraph: { spacing: { before: 360, after: 160 }, outlineLevel: 0 }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: FONT, color: DARK },
        paragraph: { spacing: { before: 280, after: 120 }, outlineLevel: 1 }
      }
    ]
  },
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      },
      {
        reference: "numbers",
        levels: [{
          level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [

      // Title block
      new Paragraph({
        children: [new TextRun({ text: "chevron::process::GUIEngine", font: "Courier New", size: 40, bold: true, color: BLUE })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Class Design Description", font: FONT, size: 26, color: MID, italics: true })],
        spacing: { before: 0, after: 60 }
      }),
      rule(),
      spacer(80),

      // What GUIEngine is
      h1("What GUIEngine Is"),
      para([
        normal("GUIEngine is the "),
        bold("owner of everything that is only valid while the GUI is alive"),
        normal(". It is the boundary between the process-level world that "),
        mono("AppProcess"),
        normal(" governs and the GUI-bound world that the chosen framework inhabits.")
      ]),
      spacer(80),
      para([
        normal("Where "),
        mono("AppProcess"),
        normal(" decides "),
        italic("when"),
        normal(" a GUI runtime exists, "),
        mono("GUIEngine"),
        normal(" decides "),
        italic("what happens while it exists"),
        normal(". That division is the foundation of Chevron\u2019s layering model.")
      ]),
      spacer(80),
      para("It is not:"),
      bullet("A GUI framework wrapper or abstraction layer"),
      bullet("A window object or window factory"),
      bullet("A service locator"),
      bullet("A business logic container"),
      spacer(80),
      para([italic("It is the environment in which all GUI-bound infrastructure lives \u2014 and the authority that governs that environment\u2019s lifetime.")]),
      spacer(160),
      rule(),

      // Layering
      h1("Where GUIEngine Sits in the Layering Model"),
      para("Chevron\u2019s architecture is built around three nested lifetime layers, each owning exactly what belongs to it:"),
      spacer(80),
      ...codeBlock([
        "Process lifetime   ->   AppProcess",
        "GUI lifetime       ->   GUIEngine",
        "Window lifetime    ->   [window envelope, TBD]",
      ]),
      spacer(120),
      para([
        mono("AppProcess"),
        normal(" is the outermost layer. It owns "),
        mono("GUIEngine"),
        normal(". "),
        mono("GUIEngine"),
        normal(" owns everything that requires the GUI framework to be alive. Nothing in the GUI layer may exist before "),
        mono("GUIEngine"),
        normal(" is initialized, and nothing in it may outlive "),
        mono("GUIEngine\u2019s"),
        normal(" shutdown.")
      ]),
      spacer(160),
      rule(),

      // The core invariant
      h1("The Core Invariant"),
      blockquote("If GUIEngine exists, the GUI framework is either initialized or about to be initialized."),
      para("The corollary is just as important:"),
      blockquote("If GUIEngine does not exist, no GUI-related object may exist."),
      para([
        normal("This invariant is what makes the rest of the system safe to reason about. It is "),
        mono("GUIEngine\u2019s"),
        normal(" job to uphold it, and "),
        mono("AppProcess\u2019s"),
        normal(" job to ensure "),
        mono("GUIEngine"),
        normal(" is only driven in ways that preserve it.")
      ]),
      spacer(160),
      rule(),

      // What problem it solves
      h1("What Problem GUIEngine Is Solving"),
      para("GUI frameworks are not passive libraries \u2014 they are environments with opinions:"),
      bullet("They carry global state that must be initialized before use"),
      bullet("They impose threading requirements that must be respected"),
      bullet("They have their own startup and shutdown sequencing rules"),
      bullet("They often assume they own the process and its mainloop"),
      spacer(80),
      para([
        normal("Without "),
        mono("GUIEngine"),
        normal(", each of these concerns falls on the user to manage manually and correctly. Chevron\u2019s job is to tame that environment \u2014 to bring the framework under a controlled lifecycle rather than letting it run freely. "),
        mono("GUIEngine"),
        normal(" is the class that performs that taming.")
      ]),
      spacer(160),
      rule(),

      // Core responsibilities
      h1("Core Responsibilities (Non-Negotiable)"),
      para("GUIEngine has exactly three responsibilities:"),
      spacer(80),
      bullet([bold("1.  "), normal("Own and control the GUI framework environment")], "numbers"),
      bullet([bold("2.  "), normal("Own all GUI-scoped infrastructure for the duration of GUI lifetime")], "numbers"),
      bullet([bold("3.  "), normal("Enforce the invariant that no GUI-bound object exists outside of GUI lifetime")], "numbers"),
      spacer(80),
      para([italic("Nothing else. If a responsibility does not clearly fit into one of those buckets, it does not belong here.")]),
      spacer(160),
      rule(),

      // What GUIEngine owns
      h1("What GUIEngine Owns"),
      para([
        normal("At the base class level, "),
        mono("GUIEngine"),
        normal(" owns all infrastructure whose lifetime is bounded by the GUI being alive. Critically, the majority of this infrastructure is "),
        bold("GUI-framework-agnostic"),
        normal(" and therefore belongs at the base level \u2014 written once and shared across all concrete implementations.")
      ]),
      spacer(80),
      para("This includes:"),
      bullet([bold("The WindowDispatcher"), normal(" \u2014 responsible for the act of window creation. Holds and executes the logic that produces new window instances when a window is requested. Does not manage what it produces.")]),
      bullet([bold("The WindowCoordinator"), normal(" \u2014 receives ownership of what WindowDispatcher produces. Tracks all live windows, manages their relationships, and is aware when the last window has closed. May signal shutdown as a result.")]),
      bullet([bold("The window envelope instances"), normal(" \u2014 each live window is represented by an envelope that bundles the raw backend window handle with per-window Chevron infrastructure (identity, lifecycle hooks, scoped services, etc.). Their lifetime is governed by WindowCoordinator.")]),
      spacer(80),
      para([
        normal("Concrete engine implementations ("),
        mono("wx::Engine"),
        normal(", "),
        mono("qt::Engine"),
        normal(", etc.) own only what is genuinely framework-specific:")
      ]),
      bullet("The framework\u2019s application object (wxApp, QApplication, etc.)"),
      bullet("The mainloop wrapper that gives Chevron control over the framework\u2019s event loop"),
      bullet("Any framework-specific initialization or teardown logic"),
      spacer(160),
      rule(),

      // What GUIEngine does NOT own
      h1("What GUIEngine Deliberately Does Not Own"),
      para([italic("This is just as important as what it does own.")]),
      spacer(80),
      para("GUIEngine does not own:"),
      bullet("Application lifetime or process startup and exit"),
      bullet("Command line parsing beyond what the backend minimally requires"),
      bullet("Business logic of any kind"),
      bullet("Non-GUI services or infrastructure"),
      spacer(80),
      para([
        normal("That boundary keeps the layering clean. "),
        mono("AppProcess"),
        normal(" governs the process. "),
        mono("GUIEngine"),
        normal(" governs the GUI environment within it. Neither reaches into the other\u2019s domain.")
      ]),
      spacer(160),
      rule(),

      // Lifetime
      h1("Lifetime of GUIEngine"),
      para([
        normal("GUIEngine is constructed by the user as a concrete implementation, configured, and then committed to "),
        mono("AppProcess"),
        normal(". From that point forward, "),
        mono("AppProcess"),
        normal(" drives it exclusively through the "),
        mono("GUIEngine"),
        normal(" interface.")
      ]),
      spacer(120),

      h2("1. Construction"),
      para([
        normal("The user constructs a concrete engine (e.g. "),
        mono("chevron::wx::Engine"),
        normal("). At this point, no GUI framework calls have occurred and no global GUI state has been touched. Configuration is still mutable. This phase exists solely to prepare the engine for commitment.")
      ]),
      spacer(80),
      para([italic("Nothing GUI-visible exists yet.")]),
      spacer(120),

      h2("2. Commitment to AppProcess"),
      para([
        normal("Ownership transfers to "),
        mono("AppProcess"),
        normal(". Configuration is effectively locked. The engine is now the chosen backend for the lifetime of the process. Still no GUI initialization, no windows, no mainloop.")
      ]),
      spacer(120),

      h2("3. Initialization"),
      para([
        normal("AppProcess instructs the engine to initialize. This is where the GUI framework comes alive: the framework\u2019s application object is created, environment assumptions are validated, and internal subsystems are prepared. The mainloop has "),
        bold("not"),
        normal(" started. Windows do "),
        bold("not"),
        normal(" exist yet.")
      ]),
      spacer(80),
      para("If initialization fails:"),
      bullet("No mainloop starts"),
      bullet("No windows are created"),
      bullet("The application can still exit cleanly"),
      spacer(120),

      h2("4. Runtime Start"),
      para([bold("This is the point of no return.")]),
      spacer(80),
      para([
        normal("AppProcess calls "),
        mono("startRuntime()"),
        normal(". The engine materializes windows through the WindowDispatcher, the WindowCoordinator begins tracking them, and the mainloop enters. From this moment, "),
        mono("startRuntime()"),
        normal(" blocks. Control flow is inside the GUI framework until shutdown.")
      ]),
      spacer(120),

      h2("5. Shutdown and Teardown"),
      para([italic("Shutdown is not the inverse of startup.")]),
      spacer(80),
      para("Shutdown may be initiated by user code, by the GUI framework itself (e.g. the last window closes), or by AppProcess. The engine must support all three origins without the caller needing to coordinate them."),
      spacer(80),
      para("During shutdown:"),
      bullet("The mainloop is stopped"),
      bullet("The WindowCoordinator winds down live windows in a controlled order"),
      bullet("Per-window infrastructure is torn down with each window envelope"),
      bullet("The GUI framework is deinitialized"),
      bullet("Control returns to AppProcess"),
      spacer(80),
      para([bold("Calling shutdown twice must be safe.")]),
      spacer(160),
      rule(),

      // Abstract base vs concrete
      h1("Abstract Base vs. Concrete Implementations"),
      para([
        normal("The base "),
        mono("GUIEngine"),
        normal(" class defines the lifecycle contract, ownership boundaries, and sequencing rules. It is the surface that "),
        mono("AppProcess"),
        normal(" sees and the only surface it is permitted to use.")
      ]),
      spacer(80),
      para("Concrete implementations inherit from this base and are responsible for exactly one thing that varies per backend: how the framework is initialized, how its mainloop is controlled, and how it is torn down. Everything else \u2014 window dispatching, window coordination, the envelope model \u2014 is handled at the base level and is not reimplemented per backend."),
      spacer(80),
      para("This means adding a new backend is a focused task: implement the framework-specific lifecycle, plug into the base infrastructure, done. The base class does the rest."),
      spacer(160),
      rule(),

      // Error handling
      h1("Error Handling Philosophy"),
      para("GUIEngine should:"),
      bullet("Fail fast on lifecycle misuse"),
      bullet("Return explicit status codes where applicable"),
      bullet("Never leave the GUI environment half-initialized or half-alive"),
      bullet("Throw on exceptional code paths"),
      spacer(80),
      para([
        bold("Note: "),
        normal("The precise boundary between returned error codes and thrown exceptions follows the same open question as AppProcess \u2014 deferred pending library-wide error handling strategy decisions.")
      ]),
      spacer(80),
      para("Examples of misuse that must be caught:"),
      bullet("Any GUI-bound operation attempted before initialization"),
      bullet("Starting the mainloop without a committed and initialized engine"),
      bullet("Initializing twice"),
      bullet("Window operations attempted after shutdown has begun"),
      spacer(160),
      rule(),

      // Public API shape
      h1("Public API Shape (Conceptual, Not Code)"),
      para([
        normal("From "),
        mono("AppProcess\u2019s"),
        normal(" perspective, the surface of "),
        mono("GUIEngine"),
        normal(" is intentionally narrow:")
      ]),
      spacer(80),
      bullet("Initialize the GUI framework"),
      bullet("Start the mainloop and block"),
      bullet("Accept a shutdown signal and tear down cleanly"),
      spacer(80),
      para([
        normal("The broader surface \u2014 window registration, dispatcher access, coordinator queries \u2014 is available to Chevron\u2019s internal infrastructure but is not part of what "),
        mono("AppProcess"),
        normal(" ever touches.")
      ]),
      spacer(80),
      para([bold("Each step is explicit. No magic. No hidden behavior.")]),
      spacer(160),
      rule(),

      // Open questions
      h1("Open Questions and Deferred Decisions"),
      para("The following are known open questions that are intentionally deferred:"),
      spacer(80),
      bullet([
        bold("Window envelope design: "),
        normal("The exact structure of the per-window envelope \u2014 what Chevron infrastructure it carries, how it is constructed, and how it relates to the raw backend window handle \u2014 is deferred to dedicated design work on the window layer.")
      ]),
      bullet([
        bold("WindowDispatcher / WindowCoordinator handoff: "),
        normal("The mechanism by which ownership of a newly constructed window transfers from WindowDispatcher to WindowCoordinator has not been designed. This is the first question to resolve when those classes are formalized.")
      ]),
      bullet([
        bold("Shutdown signal routing: "),
        normal("The precise mechanism by which a framework-initiated shutdown (e.g. last window closed) is communicated back to AppProcess has not been defined.")
      ]),
      bullet([
        bold("Error handling boundary: "),
        normal("Follows the same open question as AppProcess. Deferred pending library-wide decisions.")
      ]),
      bullet([
        bold("GUIEngine virtual interface shape: "),
        normal("The precise set of virtual methods that compose the GUIEngine contract has not yet been defined. This is the next design surface to formalize.")
      ]),
      spacer(160),
      rule(),

      // Footer
      new Paragraph({
        children: [new TextRun({ text: "Chevron Library \u2014 Internal Design Documentation", font: FONT, size: 18, color: "AAAAAA", italics: true })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 160 }
      })
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/mnt/user-data/outputs/GUIEngine_Class_Description.docx', buffer);
  console.log('Done');
});

