const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, LevelFormat, BorderStyle
} = require('docx');
const fs = require('fs');

const FONT = "Arial";
const BLUE = "2E5FA3";
const DARK = "1A1A1A";
const MID  = "444444";
const RULE_COLOR = "CCCCCC";

function rule() {
  return new Paragraph({
    children: [],
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: RULE_COLOR, space: 1 } },
    spacing: { before: 80, after: 160 }
  });
}

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, font: FONT, size: 36, bold: true, color: BLUE })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, font: FONT, size: 26, bold: true, color: DARK })]
  });
}

function para(runs, opts = {}) {
  const children = (typeof runs === 'string')
    ? [new TextRun({ text: runs, font: FONT, size: 22, color: DARK })]
    : runs;
  return new Paragraph({ children, spacing: { before: 80, after: 120 }, ...opts });
}

function bold(text, color = DARK) {
  return new TextRun({ text, font: FONT, size: 22, bold: true, color });
}

function normal(text) {
  return new TextRun({ text, font: FONT, size: 22, color: DARK });
}

function italic(text, color = MID) {
  return new TextRun({ text, font: FONT, size: 22, italics: true, color });
}

function mono(text) {
  return new TextRun({ text, font: "Courier New", size: 20, color: DARK });
}

function bullet(content, ref = "bullets") {
  const children = (typeof content === 'string')
    ? [new TextRun({ text: content, font: FONT, size: 22, color: DARK })]
    : content;
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    children,
    spacing: { before: 60, after: 60 }
  });
}

function blockquote(text) {
  return new Paragraph({
    children: [new TextRun({ text, font: FONT, size: 22, italics: true, color: "555555" })],
    indent: { left: 720 },
    border: { left: { style: BorderStyle.SINGLE, size: 12, color: BLUE, space: 10 } },
    spacing: { before: 120, after: 120 }
  });
}

function spacer(pts = 120) {
  return new Paragraph({ children: [], spacing: { before: 0, after: pts } });
}

function codeBlock(lines) {
  return lines.map((line, i) => new Paragraph({
    children: [new TextRun({ text: line, font: "Courier New", size: 20, color: "2E5FA3" })],
    spacing: { before: i === 0 ? 100 : 0, after: i === lines.length - 1 ? 100 : 0 },
    indent: { left: 720 },
    shading: { val: "clear", fill: "F4F4F4" }
  }));
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: FONT, size: 22 } } },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: FONT, color: BLUE },
        paragraph: { spacing: { before: 360, after: 160 }, outlineLevel: 0 }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: FONT, color: DARK },
        paragraph: { spacing: { before: 280, after: 120 }, outlineLevel: 1 }
      }
    ]
  },
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      },
      {
        reference: "numbers",
        levels: [{
          level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [

      // Title block
      new Paragraph({
        children: [new TextRun({ text: "chevron::process::WindowDispatcher", font: "Courier New", size: 40, bold: true, color: BLUE })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Class Design Description", font: FONT, size: 26, color: MID, italics: true })],
        spacing: { before: 0, after: 60 }
      }),
      rule(),
      spacer(80),

      // What WindowDispatcher is
      h1("What WindowDispatcher Is"),
      para([
        mono("WindowDispatcher"),
        normal(" is the "),
        bold("GUI-scoped authority for window creation"),
        normal(". It is the single point through which all window construction requests must pass, and it answers one question at the moment of each request:")
      ]),
      spacer(80),
      blockquote("Is this window allowed to exist right now, and if so \u2014 create it."),
      para([
        normal("It is not a manager, a tracker, or a policy brain. Once a window has been created and handed off, "),
        mono("WindowDispatcher"),
        normal(" is done with it. Its concern is the act of creation, not the consequences.")
      ]),
      spacer(80),
      para("It is not:"),
      bullet("A window manager or lifetime owner of windows"),
      bullet("A GUI abstraction layer"),
      bullet("An event router"),
      bullet([italic("A one-time startup mechanism \u2014 it remains an active, callable service for the entire duration of GUI lifetime")]),
      spacer(160),
      rule(),

      // Where it sits in the layering model
      h1("Where WindowDispatcher Sits in the Layering Model"),
      para([
        mono("WindowDispatcher"),
        normal(" is a GUI-scoped component that lives inside "),
        mono("GUIEngine"),
        normal(" at the base class level. It is not reimplemented by each concrete backend \u2014 it is framework-agnostic infrastructure that every backend inherits.")
      ]),
      spacer(80),
      ...codeBlock([
        "Process lifetime   ->   AppProcess",
        "GUI lifetime       ->   GUIEngine",
        "                          |- WindowDispatcher   (creation authority)",
        "                          |- WindowCoordinator  (lifetime authority)",
        "Window lifetime    ->   [window envelope, TBD]",
      ]),
      spacer(120),
      para([
        normal("The division of responsibility between "),
        mono("WindowDispatcher"),
        normal(" and "),
        mono("WindowCoordinator"),
        normal(" is deliberate and non-negotiable: "),
        mono("WindowDispatcher"),
        normal(" creates windows, "),
        mono("WindowCoordinator"),
        normal(" owns them afterward. The seam between those two classes is where a newly constructed window envelope transfers from one authority to the other. Neither class reaches into the other\u2019s domain.")
      ]),
      spacer(160),
      rule(),

      // What problem it solves
      h1("What Problem WindowDispatcher Is Solving"),
      para("Without a centralized creation authority, GUI applications tend to accumulate the same set of problems:"),
      bullet("Windows are created ad-hoc from arbitrary locations in user code"),
      bullet("No clear policy exists around when a window may or may not be created"),
      bullet("Business logic becomes tightly coupled to GUI construction details"),
      bullet("There is no clean way to re-create a window that has been closed"),
      bullet("Startup window logic cannot be reused for windows opened later at runtime"),
      spacer(80),
      para([
        mono("WindowDispatcher"),
        normal(" eliminates all of these by making window creation a governed, centralized act. User code declares window intent by registering factories. The dispatcher is the only thing that ever executes those factories, and only when the conditions are right.")
      ]),
      spacer(160),
      rule(),

      // Core responsibilities
      h1("Core Responsibilities (Non-Negotiable)"),
      para("WindowDispatcher has exactly four responsibilities:"),
      spacer(80),
      bullet([bold("1.  "), normal("Accept window factory registrations as declarative intent")], "numbers"),
      bullet([bold("2.  "), normal("Store and manage WindowInitContext instances that pair each factory with its descriptor")], "numbers"),
      bullet([bold("3.  "), normal("Materialize windows on demand by executing the appropriate factory at the right moment")], "numbers"),
      bullet([bold("4.  "), normal("Hand off newly created window envelopes to WindowCoordinator and relinquish all further involvement")], "numbers"),
      spacer(80),
      para([
        normal("That fourth responsibility is as important as any of the others. The moment "),
        mono("WindowDispatcher"),
        normal(" begins tracking focus, z-order, or the state of live windows, it has become a manager \u2014 which it must never be.")
      ]),
      spacer(160),
      rule(),

      // WindowInitContext
      h1("WindowInitContext"),
      para([
        mono("WindowDispatcher"),
        normal(" does not store raw factory callables. It stores "),
        mono("WindowInitContext"),
        normal(" instances \u2014 lightweight objects that bundle two things together:")
      ]),
      spacer(80),
      bullet([bold("A window factory"), normal(" \u2014 the callable that constructs the window envelope when invoked")]),
      bullet([bold("A window descriptor"), normal(" \u2014 a flags-based metadata object that governs the dispatch rules for this factory")]),
      spacer(80),
      para([
        normal("The descriptor is what allows the dispatcher to make informed decisions at dispatch time without containing any hardcoded policy. Flags currently envisioned include a "),
        bold("single-instance flag"),
        normal(" (this factory may not be dispatched if a live instance already exists) and a "),
        bold("main window flag"),
        normal(" (this factory produces the application\u2019s primary window).")
      ]),
      spacer(80),
      para([
        normal("When the main window flag is set, the dispatcher uses that factory to materialize the first window at runtime start. If no factory carries the flag, the first registered factory is used by default. The main window designation also carries behavioral weight at shutdown: most GUI frameworks will automatically initiate application exit when the main window closes, and Chevron respects that behavior rather than fighting it.")
      ]),
      spacer(80),
      para([
        normal("Enforcement of the single-instance constraint requires cooperation with "),
        mono("WindowCoordinator"),
        normal(", since only the coordinator has visibility into what windows are currently alive. The exact mechanism for that cooperation is a deferred design question.")
      ]),
      spacer(160),
      rule(),

      // What it doesn't own
      h1("What WindowDispatcher Deliberately Does Not Own"),
      para([italic("This boundary is just as important as what it does own.")]),
      spacer(80),
      para("WindowDispatcher does not own:"),
      bullet("The lifetime of any window it creates"),
      bullet("Knowledge of what windows are currently alive"),
      bullet("Focus, z-order, or any other live window state"),
      bullet("Shutdown logic or teardown sequencing"),
      bullet("Any GUI-framework-specific construction details"),
      spacer(80),
      para([
        normal("Once a window envelope leaves "),
        mono("WindowDispatcher"),
        normal(" and enters "),
        mono("WindowCoordinator"),
        normal(", the dispatcher has no further knowledge of or authority over it.")
      ]),
      spacer(160),
      rule(),

      // Lifetime
      h1("Lifetime of WindowDispatcher"),
      para([
        mono("WindowDispatcher"),
        normal(" is constructed as part of "),
        mono("GUIEngine"),
        normal(" at the base class level and is destroyed during GUI teardown. Its lifetime is entirely bounded by the GUI engine that owns it.")
      ]),
      spacer(80),
      blockquote("The dispatcher exists before windows, during window creation, and after windows \u2014 but windows only exist during one slice of its lifetime."),
      para("That asymmetry is intentional. The dispatcher is not defined by the windows it has created. It is defined by its readiness to create them."),
      spacer(160),
      rule(),

      // Lifecycle phases
      h1("Lifecycle of WindowDispatcher"),
      para([
        normal("The dispatcher moves through three distinct operational phases. Each phase has different rules about what is and is not legal. An internal phase state governs these transitions and makes the rules enforceable rather than merely documented.")
      ]),
      spacer(120),

      h2("1. Construction and Registration"),
      para([
        normal("Constructed as part of "),
        mono("GUIEngine"),
        normal(" during the engine\u2019s own construction. No GUI framework calls have occurred. The dispatcher is ready to accept "),
        mono("WindowInitContext"),
        normal(" registrations.")
      ]),
      spacer(80),
      para([
        normal("Factory registration is a pre-commitment activity. User code declares window intent by registering factories against the engine before committing it to "),
        mono("AppProcess"),
        normal(". At commitment, the process-level registration window closes and the factory set is effectively locked. Post-commitment registration from within the GUI layer is an intentionally deferred capability and is not part of the current design.")
      ]),
      spacer(80),
      para([italic("Factories registered here are declarative intent, not execution. No windows are created yet.")]),
      spacer(120),

      h2("2. Runtime Activation"),
      para([
        normal("When "),
        mono("AppProcess"),
        normal(" calls "),
        mono("startRuntime()"),
        normal(", the dispatcher transitions to its active phase. This is the first moment at which dispatch requests are legal.")
      ]),
      spacer(80),
      para([
        normal("The dispatcher immediately materializes the startup window \u2014 either the factory carrying the main window flag, or the first registered factory if no flag is set \u2014 and hands the resulting envelope to "),
        mono("WindowCoordinator"),
        normal(". The mainloop then enters.")
      ]),
      spacer(120),

      h2("3. Active Runtime Dispatching"),
      para([
        mono("WindowDispatcher"),
        normal(" is not a one-time startup mechanism. During normal runtime operation, dispatch requests may arrive at any time \u2014 from user interaction, application logic, or internal triggers. The dispatcher handles each request uniformly: consult the descriptor, verify constraints, execute the factory if permitted, hand off the result.")
      ]),
      spacer(80),
      para([
        normal("For factories carrying the single-instance flag, the dispatcher consults "),
        mono("WindowCoordinator"),
        normal(" to determine whether a live instance already exists before proceeding. Factories without this flag may be dispatched freely, producing as many instances as requested.")
      ]),
      spacer(120),

      h2("4. Shutdown"),
      para([
