const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, LevelFormat, BorderStyle
} = require('docx');
const fs = require('fs');

const FONT = "Arial";
const BLUE = "2E5FA3";
const DARK = "1A1A1A";
const MID  = "444444";
const RULE_COLOR = "CCCCCC";

function rule() {
  return new Paragraph({
    children: [],
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: RULE_COLOR, space: 1 } },
    spacing: { before: 80, after: 160 }
  });
}

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, font: FONT, size: 36, bold: true, color: BLUE })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, font: FONT, size: 26, bold: true, color: DARK })]
  });
}

function para(runs, opts = {}) {
  const children = (typeof runs === 'string')
    ? [new TextRun({ text: runs, font: FONT, size: 22, color: DARK })]
    : runs;
  return new Paragraph({ children, spacing: { before: 80, after: 120 }, ...opts });
}

function bold(text, color = DARK) {
  return new TextRun({ text, font: FONT, size: 22, bold: true, color });
}

function normal(text) {
  return new TextRun({ text, font: FONT, size: 22, color: DARK });
}

function italic(text, color = MID) {
  return new TextRun({ text, font: FONT, size: 22, italics: true, color });
}

function mono(text) {
  return new TextRun({ text, font: "Courier New", size: 20, color: DARK });
}

function bullet(content, ref = "bullets") {
  const children = (typeof content === 'string')
    ? [new TextRun({ text: content, font: FONT, size: 22, color: DARK })]
    : content;
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    children,
    spacing: { before: 60, after: 60 }
  });
}

function blockquote(text) {
  return new Paragraph({
    children: [new TextRun({ text, font: FONT, size: 22, italics: true, color: "555555" })],
    indent: { left: 720 },
    border: { left: { style: BorderStyle.SINGLE, size: 12, color: BLUE, space: 10 } },
    spacing: { before: 120, after: 120 }
  });
}

function spacer(pts = 120) {
  return new Paragraph({ children: [], spacing: { before: 0, after: pts } });
}

function codeBlock(lines) {
  return lines.map((line, i) => new Paragraph({
    children: [new TextRun({ text: line, font: "Courier New", size: 20, color: "2E5FA3" })],
    spacing: { before: i === 0 ? 100 : 0, after: i === lines.length - 1 ? 100 : 0 },
    indent: { left: 720 },
    shading: { val: "clear", fill: "F4F4F4" }
  }));
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: FONT, size: 22 } } },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: FONT, color: BLUE },
        paragraph: { spacing: { before: 360, after: 160 }, outlineLevel: 0 }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: FONT, color: DARK },
        paragraph: { spacing: { before: 280, after: 120 }, outlineLevel: 1 }
      }
    ]
  },
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      },
      {
        reference: "numbers",
        levels: [{
          level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [

      // Title block
      new Paragraph({
        children: [new TextRun({ text: "chevron::process::WindowHierarchy", font: "Courier New", size: 40, bold: true, color: BLUE })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Class Design Description", font: FONT, size: 26, color: MID, italics: true })],
        spacing: { before: 0, after: 60 }
      }),
      rule(),
      spacer(80),

      // What WindowHierarchy is
      h1("What WindowHierarchy Is"),
      para([
        mono("WindowHierarchy"),
        normal(" is the "),
        bold("authoritative record of parent-child relationships between live window envelopes"),
        normal(". It is a focused data structure with a focused API \u2014 its sole concern is knowing which windows are related, in what direction, and in what order they should be addressed when relationships are dissolved.")
      ]),
      spacer(80),
      para([
        normal("It does not track window state, manage lifetimes, or interact with the GUI framework. It knows only about relationships between instance IDs, and it answers questions about those relationships cleanly and without side effects.")
      ]),
      spacer(80),
      para("It is not:"),
      bullet("A window manager or lifetime authority"),
      bullet("A replacement for or competitor to the framework\u2019s own parent-child window model"),
      bullet("Aware of the underlying framework window handles or any GUI-specific details"),
      bullet("Directly accessible to user code"),
      spacer(160),
      rule(),

      // Where it sits
      h1("Where WindowHierarchy Sits in the Layering Model"),
      para([
        mono("WindowHierarchy"),
        normal(" is an internal component owned by "),
        mono("WindowCoordinator"),
        normal(". It does not sit at a named layer boundary in Chevron\u2019s lifetime hierarchy \u2014 it is a focused sub-component that the coordinator delegates relationship concerns to, keeping that logic self-contained and its own code readable.")
      ]),
      spacer(80),
      ...codeBlock([
        "Process lifetime   ->   AppProcess",
        "GUI lifetime       ->   GUIEngine",
        "                          |- WindowDispatcher    (creation authority)",
        "                          |- WindowCoordinator   (lifetime authority)",
        "                          |    |- WindowHierarchy (relationship graph)",
        "Window lifetime    ->   WindowEnvelope",
      ]),
      spacer(120),
      para([
        normal("This nesting is deliberate. Relationship tracking is a specific sub-concern of the coordinator\u2019s broader responsibility. Keeping it inside a dedicated type means the coordinator can answer relationship queries through a clean API rather than managing graph state inline. It also means "),
        mono("WindowHierarchy"),
        normal(" can evolve independently if relationship tracking needs grow more complex over time.")
      ]),
      spacer(160),
      rule(),

      // What problem it solves
      h1("What Problem WindowHierarchy Is Solving"),
      para([
        normal("GUI applications composed of multiple windows inevitably have relationships between them. A subsidiary window belongs to a parent. When that parent is closed, the framework handles the cascade \u2014 but Chevron still needs to keep its own bookkeeping consistent. Without a dedicated structure for tracking those relationships, that logic either scatters into the coordinator\u2019s general registry management or gets pushed onto individual envelopes, neither of which is clean.")
      ]),
      spacer(80),
      para([
        mono("WindowHierarchy"),
        normal(" solves this by giving relationship knowledge a single home. The coordinator registers relationships here when subsidiary windows are created and queries here during teardown to determine the correct order for winding down envelopes. The graph is always consistent with what the coordinator\u2019s live registry contains because the two are updated together.")
      ]),
      spacer(80),
      blockquote("WindowHierarchy does not manage window lifetimes. It records the relationships that the coordinator needs to reason about them correctly."),
      spacer(160),
      rule(),

      // Core responsibilities
      h1("Core Responsibilities (Non-Negotiable)"),
      para("WindowHierarchy has exactly three responsibilities:"),
      spacer(80),
      bullet([bold("1.  "), normal("Record parent-child relationships between window instance IDs when subsidiary windows are registered")], "numbers"),
      bullet([bold("2.  "), normal("Answer relationship queries from WindowCoordinator \u2014 children of a given parent, whether a relationship exists, whether a window is a root")], "numbers"),
      bullet([bold("3.  "), normal("Provide a safe teardown traversal order that addresses children before parents")], "numbers"),
      spacer(80),
      para([italic("Nothing else. WindowHierarchy is a data structure with a query API, not a service with behavior of its own.")]),
      spacer(160),
      rule(),

      // How relationships are represented
      h1("How Relationships Are Represented"),
      para([
        normal("Relationships are stored as mappings between instance IDs. A parent instance ID maps to a collection of child instance IDs, supporting the one-to-many cardinality that window hierarchies naturally require. A window with no parent is a root window. A window with no children is a leaf.")
      ]),
      spacer(80),
      para([
        normal("No pointers to "),
        mono("WindowEnvelope"),
        normal(" instances are held inside "),
        mono("WindowHierarchy"),
        normal(". This is a deliberate choice. Instance IDs are stable, non-owning references that cannot dangle. Holding pointers would create lifetime coupling between the hierarchy and the envelopes it describes, which would complicate teardown sequencing and make the coordinator\u2019s ownership story harder to reason about.")
      ]),
      spacer(80),
      para([
        normal("Individual envelopes carry no relationship data themselves. They know their own instance ID and the factory ID they were produced from, but nothing about their position in the window tree. The graph lives entirely inside "),
        mono("WindowHierarchy"),
        normal(" and is the coordinator\u2019s concern alone.")
      ]),
      spacer(160),
      rule(),

      // Relationship to the framework
      h1("Relationship to the Framework\u2019s Own Hierarchy"),
      para([
        normal("Most GUI frameworks natively support the concept of parent and subsidiary windows, and handle lifetime cascade automatically when a parent window closes \u2014 provided windows were composed correctly at construction time. Chevron embraces this behavior rather than duplicating it.")
      ]),
      spacer(80),
      para([
        mono("WindowHierarchy"),
        normal(" is not a replacement for the framework\u2019s own relationship model. It is Chevron\u2019s mirror of that model, maintained in terms that Chevron can reason about. When the framework closes subsidiary windows as a consequence of a parent closing, "),
        mono("WindowHierarchy"),
        normal(" is consulted to keep the coordinator\u2019s registry consistent with what the framework has already done \u2014 not to drive the cascade itself.")
      ]),
      spacer(80),
      para([
        normal("The only case where Chevron would need to act on hierarchy data to manage cascade manually is if a particular GUI framework does not handle subsidiary window teardown automatically. This is expected to be rare and is a deferred consideration.")
      ]),
      spacer(160),
      rule(),

      // Teardown traversal
      h1("Teardown Traversal Order"),
      para([
        normal("During "),
        mono("GUIEngine"),
        normal(" shutdown, "),
        mono("WindowCoordinator"),
        normal(" asks "),
        mono("WindowHierarchy"),
        normal(" for a safe order in which to wind down live envelopes. The rule is consistent: children are always addressed before their parents. This ensures that no envelope is wound down while another live envelope still holds it as a registered parent.")
      ]),
      spacer(80),
      para([
        normal("The traversal is a post-order walk of the relationship graph \u2014 leaf nodes first, root nodes last. For windows with no registered relationships, order relative to other roots is unspecified and does not matter.")
      ]),
      spacer(80),
      para([
        normal("As each envelope is wound down during this sequence, its entry is removed from "),
        mono("WindowHierarchy"),
        normal(" alongside its removal from the coordinator\u2019s live registry. The two structures are always kept in sync.")
      ]),
      spacer(160),
      rule(),

      // Lifetime
      h1("Lifetime of WindowHierarchy"),
      para([
        mono("WindowHierarchy"),
        normal(" is constructed as part of "),
        mono("WindowCoordinator"),
        normal(" and destroyed when the coordinator is destroyed. Its lifetime is entirely bounded by the coordinator that owns it. It holds no resources beyond its own relationship data and requires no special teardown beyond clearing that data, which happens naturally as envelopes are wound down during the shutdown sequence.")
      ]),
      spacer(80),
      para([
        normal("At the end of a clean shutdown, "),
        mono("WindowHierarchy"),
        normal(" is empty. Any entries remaining at that point would indicate envelopes that were not properly wound down \u2014 a coordinator-level correctness failure.")
      ]),
      spacer(160),
      rule(),

      // What it doesn't own
      h1("What WindowHierarchy Deliberately Does Not Own"),
      para([italic("This boundary is just as important as what it does own.")]),
      spacer(80),
      para("WindowHierarchy does not own:"),
      bullet("Any WindowEnvelope instance or pointer"),
      bullet("Knowledge of window state, visibility, focus, or any runtime GUI property"),
      bullet("Any framework window handle or backend-specific reference"),
      bullet("The logic for deciding when or whether a relationship should exist \u2014 that belongs to GUIEngine"),
      bullet("Teardown execution \u2014 it provides traversal order, WindowCoordinator acts on it"),
      spacer(160),
      rule(),

      // Error handling
      h1("Error Handling Philosophy"),
      para("WindowHierarchy should:"),
      bullet("Refuse to register a relationship where the parent instance ID is not known to the coordinator"),
      bullet("Refuse to register a relationship that would create a cycle"),
      bullet("Fail fast if queried for children of an instance ID that does not exist in the graph"),
      bullet("Never silently produce an incomplete or inconsistent traversal order"),
      spacer(80),
      para([
        bold("Note: "),
        normal("The boundary between returned error codes and thrown exceptions follows the same open question as the rest of the library \u2014 deferred pending library-wide error handling strategy decisions.")
      ]),
      spacer(160),
      rule(),

      // Open questions
      h1("Open Questions and Deferred Decisions"),
      para("The following are known open questions that are intentionally deferred:"),
      spacer(80),
      bullet([
        bold("Internal graph representation: "),
        normal("The precise data structure used to store the parent-to-children mapping \u2014 whether an adjacency list, a map of sets, or another form \u2014 is an implementation detail deferred to development.")
      ]),
      bullet([
        bold("Cycle detection strategy: "),
        normal("How and when cycles are detected during relationship registration has not been defined. Whether this is checked eagerly on every registration or lazily during traversal is an open question.")
      ]),
      bullet([
        bold("Query API completeness: "),
        normal("The full set of queries WindowCoordinator will need from WindowHierarchy \u2014 beyond children-of, root-check, and teardown traversal \u2014 will become clearer as the coordinator\u2019s implementation matures. Additional query methods may be introduced.")
      ]),
      bullet([
        bold("Manual cascade handling: "),
        normal("The mechanism by which Chevron handles subsidiary window teardown for frameworks that do not automatically cascade on parent close is deferred. WindowHierarchy\u2019s traversal order is the foundation for this but the driving logic has not been designed.")
      ]),
      bullet([
        bold("Error handling boundary: "),
        normal("Follows the same open question as the rest of the library. Deferred pending library-wide decisions.")
      ]),
      spacer(160),
      rule(),

      // Footer
      new Paragraph({
        children: [new TextRun({ text: "Chevron Library \u2014 Internal Design Documentation", font: FONT, size: 18, color: "AAAAAA", italics: true })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 160 }
      })
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/mnt/user-data/outputs/WindowHierarchy_Class_Description.docx', buffer);
  console.log('Done');
});

