const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, LevelFormat, BorderStyle
} = require('docx');
const fs = require('fs');

const FONT = "Arial";
const BLUE = "2E5FA3";
const DARK = "1A1A1A";
const MID  = "444444";
const RULE_COLOR = "CCCCCC";

function rule() {
  return new Paragraph({
    children: [],
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: RULE_COLOR, space: 1 } },
    spacing: { before: 80, after: 160 }
  });
}

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, font: FONT, size: 36, bold: true, color: BLUE })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, font: FONT, size: 26, bold: true, color: DARK })]
  });
}

function para(runs, opts = {}) {
  const children = (typeof runs === 'string')
    ? [new TextRun({ text: runs, font: FONT, size: 22, color: DARK })]
    : runs;
  return new Paragraph({ children, spacing: { before: 80, after: 120 }, ...opts });
}

function bold(text, color = DARK) {
  return new TextRun({ text, font: FONT, size: 22, bold: true, color });
}

function normal(text) {
  return new TextRun({ text, font: FONT, size: 22, color: DARK });
}

function italic(text, color = MID) {
  return new TextRun({ text, font: FONT, size: 22, italics: true, color });
}

function mono(text) {
  return new TextRun({ text, font: "Courier New", size: 20, color: DARK });
}

function bullet(content, ref = "bullets") {
  const children = (typeof content === 'string')
    ? [new TextRun({ text: content, font: FONT, size: 22, color: DARK })]
    : content;
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    children,
    spacing: { before: 60, after: 60 }
  });
}

function blockquote(text) {
  return new Paragraph({
    children: [new TextRun({ text, font: FONT, size: 22, italics: true, color: "555555" })],
    indent: { left: 720 },
    border: { left: { style: BorderStyle.SINGLE, size: 12, color: BLUE, space: 10 } },
    spacing: { before: 120, after: 120 }
  });
}

function spacer(pts = 120) {
  return new Paragraph({ children: [], spacing: { before: 0, after: pts } });
}

function codeBlock(lines) {
  return lines.map((line, i) => new Paragraph({
    children: [new TextRun({ text: line, font: "Courier New", size: 20, color: "2E5FA3" })],
    spacing: { before: i === 0 ? 100 : 0, after: i === lines.length - 1 ? 100 : 0 },
    indent: { left: 720 },
    shading: { val: "clear", fill: "F4F4F4" }
  }));
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: FONT, size: 22 } } },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: FONT, color: BLUE },
        paragraph: { spacing: { before: 360, after: 160 }, outlineLevel: 0 }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: FONT, color: DARK },
        paragraph: { spacing: { before: 280, after: 120 }, outlineLevel: 1 }
      }
    ]
  },
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      },
      {
        reference: "numbers",
        levels: [{
          level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [

      // Title block
      new Paragraph({
        children: [new TextRun({ text: "chevron::process::WindowEnvelope", font: "Courier New", size: 40, bold: true, color: BLUE })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Class Design Description", font: FONT, size: 26, color: MID, italics: true })],
        spacing: { before: 0, after: 60 }
      }),
      rule(),
      spacer(80),

      // What WindowEnvelope is
      h1("What WindowEnvelope Is"),
      para([
        mono("WindowEnvelope"),
        normal(" is the "),
        bold("per-window infrastructure container"),
        normal(" that represents a single live window within Chevron\u2019s runtime. It bundles the raw backend window handle produced by a user-supplied factory with the identity, lifecycle machinery, and per-window infrastructure that Chevron provides unconditionally for every window it governs.")
      ]),
      spacer(80),
      para([
        normal("It is not the framework window itself. It is the structure that surrounds that window \u2014 giving it a stable identity within Chevron, a home for its infrastructure, and a handle through which every upstream class in the system can reason about it uniformly regardless of what GUI framework is underneath.")
      ]),
      spacer(80),
      para([
        normal("It is not inheritable. Extensibility is provided through "),
        mono("WindowComponentStore"),
        normal(", the typed component container the envelope owns. User code never subclasses "),
        mono("WindowEnvelope"),
        normal(" \u2014 it extends what lives inside it.")
      ]),
      spacer(80),
      para("It is not:"),
      bullet("The backend window object or a wrapper around its API"),
      bullet("A window manager or event router"),
      bullet("User-constructible directly \u2014 Chevron owns the construction pathway"),
      bullet("A base class for user-defined window types"),
      spacer(160),
      rule(),

      // Where it sits
      h1("Where WindowEnvelope Sits in the Layering Model"),
      para([
        mono("WindowEnvelope"),
        normal(" occupies the innermost named layer of Chevron\u2019s lifetime hierarchy. Every instance is produced by "),
        mono("WindowDispatcher"),
        normal(" via a factory call and immediately transferred to "),
        mono("WindowCoordinator"),
        normal(", which owns it for the remainder of its lifetime. The envelope exists only while the GUI engine is active.")
      ]),
      spacer(80),
      ...codeBlock([
        "Process lifetime   ->   AppProcess",
        "GUI lifetime       ->   GUIEngine",
        "                          |- WindowDispatcher    (creation authority)",
        "                          |- WindowCoordinator   (lifetime authority)",
        "                          |    |- WindowHierarchy (relationship graph)",
        "Window lifetime    ->   WindowEnvelope",
        "                          |- WindowComponentStore (per-window components)",
      ]),
      spacer(120),
      para([
        normal("The envelope is the unit of currency in Chevron\u2019s window layer. Every operation that "),
        mono("WindowCoordinator"),
        normal(" performs \u2014 tracking, querying, teardown ordering \u2014 is performed on envelopes. Every operation that "),
        mono("GUIEngine"),
        normal(" orchestrates \u2014 subsidiary window parenting, shutdown sequencing, lifecycle event propagation \u2014 is performed through envelopes. The uniform handle the envelope provides is what allows upstream classes to reason about any window without knowing anything about the underlying framework.")
      ]),
      spacer(160),
      rule(),

      // What problem it solves
      h1("What Problem WindowEnvelope Is Solving"),
      para([
        normal("Without a uniform per-window container, Chevron has no clean way to associate its own infrastructure with a live window. The framework window handle is a raw pointer with no Chevron semantics attached. The coordinator can track it by address, but it cannot ask it for a logging context, a memory arena, or a viewport system \u2014 because those things have nowhere to live.")
      ]),
      spacer(80),
      para([
        mono("WindowEnvelope"),
        normal(" solves this by being the place those things live. It gives every window a stable Chevron identity and a structured home for per-window infrastructure. Because the envelope is always present and always uniformly structured, any Chevron subsystem can reach into any live window\u2019s envelope and reliably find the components it needs \u2014 without knowing anything about the specific window, its factory, or the framework behind it.")
      ]),
      spacer(80),
      para([
        normal("This is the mechanism by which per-window infrastructure becomes a first-class library feature rather than something each application has to wire up manually.")
      ]),
      spacer(160),
      rule(),

      // Core responsibilities
      h1("Core Responsibilities (Non-Negotiable)"),
      para("WindowEnvelope has exactly four responsibilities:"),
      spacer(80),
      bullet([bold("1.  "), normal("Hold the raw backend window handle for the duration of the window\u2019s lifetime")], "numbers"),
      bullet([bold("2.  "), normal("Carry the identity information Chevron assigns \u2014 instance ID, factory ID, and window kind")], "numbers"),
      bullet([bold("3.  "), normal("Own the WindowComponentStore and guarantee base components are populated unconditionally at construction")], "numbers"),
      bullet([bold("4.  "), normal("Expose a lifecycle hook surface that Chevron\u2019s internal infrastructure can bind into")], "numbers"),
      spacer(80),
      para([italic("Nothing else. The envelope is a structured container with a governed lifetime, not a service or a policy class.")]),
      spacer(160),
      rule(),

      // What it carries
      h1("What WindowEnvelope Carries"),

      h2("The Backend Window Handle"),
      para([
        normal("The raw handle to the framework window \u2014 a "),
        mono("wxFrame*"),
        normal(", a "),
        mono("QMainWindow*"),
        normal(", or equivalent \u2014 produced by the user\u2019s factory callable. This is the one genuinely framework-specific piece inside an otherwise framework-agnostic structure. It is required and always present. Its lifetime is governed by the envelope: Chevron owns the handle from the moment the envelope is constructed and is responsible for its destruction during teardown.")
      ]),
      spacer(120),

      h2("Identity"),
      para("The envelope carries three stable identity values, all set at construction and immutable for the envelope\u2019s lifetime:"),
      spacer(80),
      bullet([
        bold("Instance ID: "),
        normal("A unique sequential identifier assigned by WindowCoordinator at the moment it takes ownership of the envelope. This is the envelope\u2019s identity within Chevron \u2014 the handle by which upstream classes target operations against this specific live window.")
      ]),
      bullet([
        bold("Factory ID: "),
        normal("The identifier of the WindowFactory that produced this envelope, embedded at dispatch time. This identifies the kind of window this envelope represents and is used by WindowCoordinator for single-instance queries and by-factory filtering.")
      ]),
      bullet([
        bold("Window kind: "),
        normal("A WindowKind enumeration value \u2014 either regular or subsidiary \u2014 set at dispatch time based on how the factory was dispatched. This is structural information, not a runtime state. A regular window is a top-level window. A subsidiary window was dispatched with a declared parent and its backend window was constructed with that parent relationship made real through the framework.")
      ]),
      spacer(120),

      h2("WindowComponentStore"),
      para([
        normal("The envelope owns a "),
        mono("WindowComponentStore"),
        normal(" \u2014 a type-keyed component container that holds all per-window infrastructure associated with this window instance. Each component is a distinct named type. Components are stored under "),
        mono("std::type_index"),
        normal(" keys and retrieved by type, with no shared base class required.")
      ]),
      spacer(80),
      para([
        normal("Chevron populates a set of "),
        bold("base components"),
