const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, LevelFormat, BorderStyle
} = require('docx');
const fs = require('fs');

const FONT = "Arial";
const BLUE = "2E5FA3";
const DARK = "1A1A1A";
const MID  = "444444";
const RULE_COLOR = "CCCCCC";

function rule() {
  return new Paragraph({
    children: [],
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: RULE_COLOR, space: 1 } },
    spacing: { before: 80, after: 160 }
  });
}

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, font: FONT, size: 36, bold: true, color: BLUE })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, font: FONT, size: 26, bold: true, color: DARK })]
  });
}

function para(runs, opts = {}) {
  const children = (typeof runs === 'string')
    ? [new TextRun({ text: runs, font: FONT, size: 22, color: DARK })]
    : runs;
  return new Paragraph({ children, spacing: { before: 80, after: 120 }, ...opts });
}

function bold(text, color = DARK) {
  return new TextRun({ text, font: FONT, size: 22, bold: true, color });
}

function normal(text) {
  return new TextRun({ text, font: FONT, size: 22, color: DARK });
}

function italic(text, color = MID) {
  return new TextRun({ text, font: FONT, size: 22, italics: true, color });
}

function mono(text) {
  return new TextRun({ text, font: "Courier New", size: 20, color: DARK });
}

function bullet(content, ref = "bullets") {
  const children = (typeof content === 'string')
    ? [new TextRun({ text: content, font: FONT, size: 22, color: DARK })]
    : content;
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    children,
    spacing: { before: 60, after: 60 }
  });
}

function blockquote(text) {
  return new Paragraph({
    children: [new TextRun({ text, font: FONT, size: 22, italics: true, color: "555555" })],
    indent: { left: 720 },
    border: { left: { style: BorderStyle.SINGLE, size: 12, color: BLUE, space: 10 } },
    spacing: { before: 120, after: 120 }
  });
}

function spacer(pts = 120) {
  return new Paragraph({ children: [], spacing: { before: 0, after: pts } });
}

function codeBlock(lines) {
  return lines.map((line, i) => new Paragraph({
    children: [new TextRun({ text: line, font: "Courier New", size: 20, color: "2E5FA3" })],
    spacing: { before: i === 0 ? 100 : 0, after: i === lines.length - 1 ? 100 : 0 },
    indent: { left: 720 },
    shading: { val: "clear", fill: "F4F4F4" }
  }));
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: FONT, size: 22 } } },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: FONT, color: BLUE },
        paragraph: { spacing: { before: 360, after: 160 }, outlineLevel: 0 }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: FONT, color: DARK },
        paragraph: { spacing: { before: 280, after: 120 }, outlineLevel: 1 }
      }
    ]
  },
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      },
      {
        reference: "numbers",
        levels: [{
          level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [

      // Title block
      new Paragraph({
        children: [new TextRun({ text: "chevron::process::WindowInitContext", font: "Courier New", size: 40, bold: true, color: BLUE })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Class Design Description", font: FONT, size: 26, color: MID, italics: true })],
        spacing: { before: 0, after: 60 }
      }),
      rule(),
      spacer(80),

      // What WindowInitContext is
      h1("What WindowInitContext Is"),
      para([
        mono("WindowInitContext"),
        normal(" is the "),
        bold("dispatch-time initialization token"),
        normal(" that Chevron assembles and passes into a factory callable at the moment a window is created. It is Chevron\u2019s side of the factory contract \u2014 the structured object that authorizes and parameterizes the construction of a "),
        mono("WindowEnvelope"),
        normal(".")
      ]),
      spacer(80),
      para([
        normal("It exists for the duration of exactly one factory invocation. It is not constructed by user code, not stored after the factory returns, and not reused across dispatch calls. Its lifetime is the factory call itself.")
      ]),
      spacer(80),
      para([
        normal("It serves two distinct audiences within that single invocation: Chevron\u2019s own envelope construction function, which consumes the internal bootstrapping data it carries, and the user\u2019s factory body, which may query it for dispatch-time information needed to construct the backend window correctly.")
      ]),
      spacer(80),
      para("It is not:"),
      bullet("A configuration object the user builds or customizes"),
      bullet("A service locator or general-purpose context object"),
      bullet("Reusable or storable beyond the factory call it was assembled for"),
      bullet("A channel for passing user-defined construction parameters \u2014 that responsibility belongs to the factory callable itself"),
      spacer(160),
      rule(),

      // Where it sits
      h1("Where WindowInitContext Sits in the Layering Model"),
      para([
        mono("WindowInitContext"),
        normal(" does not occupy a persistent position in the runtime hierarchy. It is a transient object that materializes at the dispatch boundary \u2014 the seam between "),
        mono("WindowDispatcher"),
        normal(" firing a factory and "),
        mono("WindowEnvelope"),
        normal(" coming into existence \u2014 and disappears once that boundary has been crossed.")
      ]),
      spacer(80),
      ...codeBlock([
        "Process lifetime   ->   AppProcess",
        "GUI lifetime       ->   GUIEngine",
        "                          |- WindowDispatcher    (creation authority)",
        "                          |    |- [WindowInitContext lives here, transiently]",
        "                          |- WindowCoordinator   (lifetime authority)",
        "Window lifetime    ->   WindowEnvelope",
      ]),
      spacer(120),
      para([
        normal("Conceptually it sits at the seam between the dispatcher and the envelope. "),
        mono("GUIEngine"),
        normal(" assembles it, the dispatcher passes it into the factory call, the factory uses it to construct the backend window and hand everything to Chevron\u2019s envelope construction function, and then it is gone. No class in the system holds a reference to it after the factory returns.")
      ]),
      spacer(160),
      rule(),

      // What problem it solves
      h1("What Problem WindowInitContext Is Solving"),
      para([
        normal("The factory callable has a fixed signature: it accepts a "),
        mono("WindowInitContext"),
        normal(" and returns a "),
        mono("std::unique_ptr<WindowEnvelope>"),
        normal(". This constraint exists because Chevron needs to guarantee that every envelope is constructed through a controlled pathway \u2014 one where the internal identity, component bootstrapping, and structural metadata are always correctly initialized.")
      ]),
      spacer(80),
      para([
        normal("Without "),
        mono("WindowInitContext"),
        normal(", there is no mechanism to enforce that guarantee. A factory that constructs a "),
        mono("WindowEnvelope"),
        normal(" without Chevron\u2019s involvement could produce an envelope with no instance ID, no base components, and no valid place in the coordinator\u2019s registry. The context is the token that makes construction legitimate \u2014 it cannot be forged by user code, and without it Chevron\u2019s envelope construction function will not proceed.")
      ]),
      spacer(80),
      para([
        normal("At the same time, the context gives the factory body access to the one piece of Chevron-managed information that user code genuinely cannot obtain any other way: the parent window handle for subsidiary windows. That handle lives inside another live envelope in "),
        mono("WindowCoordinator\u2019s"),
        normal(" registry. The context is the bridge that carries it out to where it is needed.")
      ]),
      spacer(160),
      rule(),

      // Core responsibilities
      h1("Core Responsibilities (Non-Negotiable)"),
      para("WindowInitContext has exactly two responsibilities:"),
      spacer(80),
      bullet([bold("1.  "), normal("Carry Chevron\u2019s internal dispatch-time data into the envelope construction function, authorizing and parameterizing the construction of a valid WindowEnvelope")], "numbers"),
      bullet([bold("2.  "), normal("Expose dispatch-time information to the factory body that user code needs to construct the backend window correctly \u2014 most importantly, the parent window handle for subsidiary window dispatches")], "numbers"),
      spacer(80),
      para([italic("Nothing else. WindowInitContext is a transient token, not a service. It carries information in one direction \u2014 from Chevron into the factory \u2014 and is consumed once.")]),
      spacer(160),
      rule(),

      // What it carries
      h1("What WindowInitContext Carries"),

      h2("Chevron-Internal Data"),
      para([
        normal("The internal contents of "),
        mono("WindowInitContext"),
        normal(" are consumed exclusively by Chevron\u2019s envelope construction function. User code has no reason to interact with them and they are not part of the public-facing API of the context. They include at minimum the dispatch identity information \u2014 the factory ID being dispatched, the "),
        mono("WindowKind"),
        normal(" for this dispatch, and whatever internal bootstrapping tokens the "),
        mono("WindowComponentStore"),
        normal(" initialization requires. The precise internal contents are deferred to the PWI design phase.")
      ]),
      spacer(120),

      h2("The Parent Window Handle"),
      para([
        normal("For subsidiary window dispatches, the context carries the parent window handle retrieved by "),
        mono("GUIEngine"),
        normal(" from the parent envelope\u2019s backend window reference. This is the one piece of information the factory body may need that it cannot obtain from any other source.")
      ]),
      spacer(80),
      para([
        normal("The handle is surfaced through a typed accessor \u2014 "),
        mono("getParentAs<T>()"),
        normal(" \u2014 where T is the framework-specific window type the factory expects. Since the factory author already knows which GUI framework is in use, the cast is safe and the correct type is always known at the call site. Chevron stores the handle internally as a "),
        mono("void*"),
        normal(" and the accessor performs the cast, keeping the context itself framework-agnostic while giving the factory body a clean, type-safe retrieval path.")
      ]),
      spacer(80),
      para([
        normal("For regular top-level window dispatches, the parent handle slot is absent. Querying it in that context is a misuse and must be caught. The "),
        mono("WindowKind"),
        normal(" carried by the context gives the factory body a clean way to branch on this if needed.")
      ]),
      spacer(160),
      rule(),

      // User-defined construction parameters
      h1("User-Defined Construction Parameters"),
      para([
        mono("WindowInitContext"),
        normal(" deliberately does not provide a mechanism for passing user-defined construction parameters into the factory. That is not its responsibility. The factory callable itself is the correct vehicle for that.")
      ]),
      spacer(80),
      para([
        normal("Because the factory is any callable with the correct signature \u2014 not just a plain function \u2014 it can close over whatever context it needs. A lambda captures local variables from the registration site. A functor class holds member state and exposes "),
        mono("operator()"),
        normal(" with the required signature. Either approach gives the factory body access to application-specific construction data \u2014 settings objects, database handles, configuration structs, whatever the window requires \u2014 without Chevron needing to know anything about it.")
      ]),
      spacer(80),
      para([
        normal("This is not a workaround. It is the intended model. The factory is a closure and closures carry their own context. Chevron provides "),
        mono("WindowInitContext"),
        normal(" for the things only Chevron can provide. Everything else is the factory author\u2019s domain.")
      ]),
      spacer(160),
      rule(),

      // Lifetime and non-copyability
      h1("Lifetime and Ownership"),
      para([
        mono("WindowInitContext"),
        normal(" is assembled by "),
        mono("GUIEngine"),
        normal(" at dispatch time, passed into the factory callable, and consumed by Chevron\u2019s envelope construction function before the factory returns. It does not outlive the factory call.")
      ]),
      spacer(80),
      para([
        normal("To enforce this, "),
        mono("WindowInitContext"),
        normal(" is non-copyable and its constructor is not accessible to user code. It cannot be stored, forwarded, or reused. A factory that attempts to retain a reference to the context beyond the scope of its invocation is producing undefined behavior.")
      ]),
      spacer(80),
      blockquote("WindowInitContext exists for the duration of one factory call. It enters with the dispatch, it leaves with the envelope. Nothing holds it after that."),
      spacer(160),
      rule(),

      // What it doesn't own
      h1("What WindowInitContext Deliberately Does Not Own"),
      para([italic("This boundary is just as important as what it does carry.")]),
      spacer(80),
      para("WindowInitContext does not own:"),
      bullet("Any WindowEnvelope instance \u2014 it authorizes construction, it does not perform it"),
      bullet("Any user-defined construction parameters \u2014 those belong to the factory callable"),
      bullet("Any persistent reference to the parent envelope or the coordinator\u2019s registry"),
      bullet("Knowledge of what happens after the factory returns"),
      bullet("Any state that persists between dispatch calls"),
      spacer(160),
      rule(),

      // Error handling
      h1("Error Handling Philosophy"),
      para("WindowInitContext and the dispatch pathway around it should:"),
      bullet([normal("Refuse construction of a "), mono("WindowEnvelope"), normal(" if the context was not legitimately assembled by Chevron at dispatch time")]),
      bullet([normal("Catch any attempt to query the parent handle on a context assembled for a regular window dispatch")]),
      bullet([normal("Treat any attempt to construct or copy a "), mono("WindowInitContext"), normal(" outside of the dispatch pathway as a hard error")]),
      spacer(80),
      para([
        bold("Note: "),
        normal("The boundary between returned error codes and thrown exceptions follows the same open question as the rest of the library \u2014 deferred pending library-wide error handling strategy decisions.")
      ]),
      spacer(160),
      rule(),

      // Open questions
      h1("Open Questions and Deferred Decisions"),
      para("The following are known open questions that are intentionally deferred:"),
      spacer(80),
      bullet([
        bold("Internal contents: "),
        normal("The precise internal data carried by WindowInitContext beyond the parent handle \u2014 specifically the bootstrapping tokens consumed by the envelope construction function during base component initialization \u2014 is deferred to dedicated PWI design work.")
      ]),
      bullet([
        bold("Envelope construction function name and signature: "),
        normal("The Chevron-provided function that accepts the backend window handle and WindowInitContext to produce a WindowEnvelope exists as a defined concept but its precise name, namespace, and C++ signature have not been finalized.")
      ]),
      bullet([
        bold("Parent handle storage type: "),
        normal("The void* approach for storing the parent handle internally is a workable baseline. A more type-safe per-backend accessor variant may replace or supplement it as the supported backend set solidifies.")
      ]),
      bullet([
        bold("WindowKind exposure: "),
        normal("Whether WindowKind is directly queryable by the factory body via the context, or whether it is purely internal, has not been decided. It is available within the context but its public surface is deferred.")
      ]),
      bullet([
        bold("Move semantics: "),
        normal("Whether WindowInitContext is move-only or entirely immovable \u2014 and what the practical implications of that choice are for the dispatch call chain \u2014 is an implementation detail deferred to development.")
      ]),
      bullet([
        bold("Error handling boundary: "),
        normal("Follows the same open question as the rest of the library. Deferred pending library-wide decisions.")
      ]),
      spacer(160),
      rule(),

      // Footer
      new Paragraph({
        children: [new TextRun({ text: "Chevron Library \u2014 Internal Design Documentation", font: FONT, size: 18, color: "AAAAAA", italics: true })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 160 }
      })
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/mnt/user-data/outputs/WindowInitContext_Class_Description.docx', buffer);
  console.log('Done');
});

