const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, LevelFormat, BorderStyle
} = require('docx');
const fs = require('fs');

const FONT = "Arial";
const BLUE = "2E5FA3";
const DARK = "1A1A1A";
const MID  = "444444";
const RULE_COLOR = "CCCCCC";

function rule() {
  return new Paragraph({
    children: [],
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: RULE_COLOR, space: 1 } },
    spacing: { before: 80, after: 160 }
  });
}

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, font: FONT, size: 36, bold: true, color: BLUE })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, font: FONT, size: 26, bold: true, color: DARK })]
  });
}

function para(runs, opts = {}) {
  const children = (typeof runs === 'string')
    ? [new TextRun({ text: runs, font: FONT, size: 22, color: DARK })]
    : runs;
  return new Paragraph({ children, spacing: { before: 80, after: 120 }, ...opts });
}

function bold(text, color = DARK) {
  return new TextRun({ text, font: FONT, size: 22, bold: true, color });
}

function normal(text) {
  return new TextRun({ text, font: FONT, size: 22, color: DARK });
}

function italic(text, color = MID) {
  return new TextRun({ text, font: FONT, size: 22, italics: true, color });
}

function mono(text) {
  return new TextRun({ text, font: "Courier New", size: 20, color: DARK });
}

function bullet(content, ref = "bullets") {
  const children = (typeof content === 'string')
    ? [new TextRun({ text: content, font: FONT, size: 22, color: DARK })]
    : content;
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    children,
    spacing: { before: 60, after: 60 }
  });
}

function blockquote(text) {
  return new Paragraph({
    children: [new TextRun({ text, font: FONT, size: 22, italics: true, color: "555555" })],
    indent: { left: 720 },
    border: { left: { style: BorderStyle.SINGLE, size: 12, color: BLUE, space: 10 } },
    spacing: { before: 120, after: 120 }
  });
}

function spacer(pts = 120) {
  return new Paragraph({ children: [], spacing: { before: 0, after: pts } });
}

function codeBlock(lines) {
  return lines.map((line, i) => new Paragraph({
    children: [new TextRun({ text: line, font: "Courier New", size: 20, color: "2E5FA3" })],
    spacing: { before: i === 0 ? 100 : 0, after: i === lines.length - 1 ? 100 : 0 },
    indent: { left: 720 },
    shading: { val: "clear", fill: "F4F4F4" }
  }));
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: FONT, size: 22 } } },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: FONT, color: BLUE },
        paragraph: { spacing: { before: 360, after: 160 }, outlineLevel: 0 }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: FONT, color: DARK },
        paragraph: { spacing: { before: 280, after: 120 }, outlineLevel: 1 }
      }
    ]
  },
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      },
      {
        reference: "numbers",
        levels: [{
          level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [

      // Title block
      new Paragraph({
        children: [new TextRun({ text: "chevron::process::WindowingSubsystem", font: "Courier New", size: 40, bold: true, color: BLUE })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Class Design Description", font: FONT, size: 26, color: MID, italics: true })],
        spacing: { before: 0, after: 60 }
      }),
      rule(),
      spacer(80),

      // What WindowingSubsystem is
      h1("What WindowingSubsystem Is"),
      para([
        mono("WindowingSubsystem"),
        normal(" is the "),
        bold("public-facing projection of GUIEngine\u2019s windowing capability"),
        normal(". It is the surface through which user code interacts with windows \u2014 registering factories, dispatching windows, querying live instances, and managing per-window components \u2014 without ever touching the internal classes that make those operations possible.")
      ]),
      spacer(80),
      para([
        normal("It does not own the windowing infrastructure. It holds non-owning references to "),
        mono("WindowDispatcher"),
        normal(" and "),
        mono("WindowCoordinator"),
        normal(", which live as first-class members of "),
        mono("GUIEngine"),
        normal(" and retain their full independence for internal operations. "),
        mono("WindowingSubsystem"),
        normal(" orchestrates their collaboration on behalf of user code and projects that collaboration as a coherent, focused API.")
      ]),
      spacer(80),
      para("It is not:"),
      bullet("An owner of any windowing infrastructure"),
      bullet([
        normal("A replacement for "),
        mono("GUIEngine"),
        normal(" \u2014 it is a projection of one aspect of it")
      ]),
      bullet("A lifecycle authority of any kind"),
      bullet([
        normal("The channel through which "),
        mono("GUIEngine"),
        normal(" handles its own internal windowing operations \u2014 those bypass this class entirely")
      ]),
      spacer(160),
      rule(),

      // Where it sits
      h1("Where WindowingSubsystem Sits in the Layering Model"),
      para([
        mono("WindowingSubsystem"),
        normal(" is owned by "),
        mono("GUIEngine"),
        normal(" and lives at the GUI lifetime layer alongside the components it references. It is not a layer unto itself \u2014 it is a focused surface projected over that layer for user code\u2019s benefit.")
      ]),
      spacer(80),
      ...codeBlock([
        "Process lifetime   ->   AppProcess",
        "GUI lifetime       ->   GUIEngine",
        "                          |- WindowDispatcher      (creation authority)    <--+",
        "                          |- WindowCoordinator     (lifetime authority)    <--+-- referenced",
        "                          |- WindowingSubsystem    (user-facing projection)---+   not owned",
        "Window lifetime    ->   WindowEnvelope",
      ]),
      spacer(120),
      para([
        normal("The components "),
        mono("WindowingSubsystem"),
        normal(" references \u2014 "),
        mono("WindowDispatcher"),
        normal(" and "),
        mono("WindowCoordinator"),
        normal(" \u2014 are constructed and owned by "),
        mono("GUIEngine"),
        normal(". They exist independently of "),
        mono("WindowingSubsystem"),
        normal(" and continue to participate in internal "),
        mono("GUIEngine"),
        normal(" operations that never surface through this class at all. "),
        mono("WindowingSubsystem"),
        normal(" is one view over those components, not their container.")
      ]),
      spacer(160),
      rule(),

      // What problem it solves
      h1("What Problem WindowingSubsystem Is Solving"),
      para([
        normal("As "),
        mono("GUIEngine"),
        normal("\u2019s windowing capabilities grow, every user-facing windowing operation would naturally accumulate on "),
        mono("GUIEngine"),
        normal("\u2019s own API \u2014 factory registration, window dispatch, component access, live window queries, subsidiary window parenting. None of these belong to "),
        mono("GUIEngine"),
        normal("\u2019s actual identity, which is lifecycle governance. Letting them accumulate there produces a class that is simultaneously a lifecycle authority and an operational windowing API, two responsibilities that have no business sharing a surface.")
      ]),
      spacer(80),
      para([
        mono("WindowingSubsystem"),
        normal(" solves this by giving those operations a coherent home. "),
        mono("GUIEngine"),
        normal("\u2019s API stays focused on what it actually governs: initialization, mainloop control, and shutdown. Everything a user needs to do with windows flows through "),
        mono("engine.windowing()"),
        normal(" instead, which reads clearly and separates concerns without reorganizing the underlying infrastructure.")
      ]),
      spacer(80),
      para([
        normal("This is the first instance of an explicit repeatable pattern in Chevron: when a cluster of internal components together form a coherent user-facing capability, a dedicated projection class surfaces that capability cleanly without those components surrendering their independence.")
      ]),
      spacer(160),
      rule(),

      // Core responsibilities
      h1("Core Responsibilities (Non-Negotiable)"),
      para("WindowingSubsystem has exactly two responsibilities:"),
      spacer(80),
      bullet([bold("1.  "), normal("Orchestrate user-initiated collaborations between WindowDispatcher and WindowCoordinator, presenting the results as a coherent windowing API")], "numbers"),
      bullet([bold("2.  "), normal("Serve as the sole public-facing surface for all windowing operations, from factory registration through runtime window management")], "numbers"),
      spacer(80),
      para([italic("Internal collaborations between WindowDispatcher and WindowCoordinator that are driven by GUIEngine\u2019s own lifecycle operations do not pass through WindowingSubsystem. This class exists exclusively for operations initiated by user code.")]),
      spacer(160),
      rule(),

      // What it references
      h1("What WindowingSubsystem References"),
      para([
        mono("WindowingSubsystem"),
        normal(" holds non-owning references to exactly two components, both of which are owned by "),
        mono("GUIEngine"),
        normal(":")
      ]),
      spacer(80),
      bullet([
        bold("WindowDispatcher"),
        normal(" \u2014 reached for all factory registration and window dispatch operations. The subsystem registers factories against it on the user\u2019s behalf and instructs it to fire when a dispatch is requested.")
      ]),
      bullet([
        bold("WindowCoordinator"),
        normal(" \u2014 reached for all live window queries, component access, and subsidiary window parenting operations. The subsystem resolves parent envelopes through it and queries it for live window state on the user\u2019s behalf.")
      ]),
      spacer(80),
      para([
        normal("These references are injected by "),
        mono("GUIEngine"),
        normal(" at construction time. "),
        mono("WindowingSubsystem"),
        normal(" never reaches into "),
        mono("GUIEngine"),
        normal(" itself, and it does not hold references to other subsystem projections. The internal components are the shared foundation \u2014 projections are independent views over them.")
      ]),
      spacer(160),
      rule(),

      // The subsystem projection pattern
      h1("The Subsystem Projection Pattern"),
      para([
        mono("WindowingSubsystem"),
        normal(" establishes an explicit architectural pattern that Chevron applies consistently as the library grows. Whenever a cluster of internal components together form a coherent user-facing capability, a dedicated projection class surfaces that capability without those components surrendering their independence.")
      ]),
      spacer(80),
      para("The pattern has three consistent properties across all instances:"),
      bullet([
        bold("The projection does not own its components. "),
        normal("Ownership stays with the class that constructed them. The projection holds non-owning references and is destroyed before its components.")
      ]),
      bullet([
        bold("The projection does not intercept internal operations. "),
        normal("Components continue to collaborate directly for internal purposes. The projection only handles operations that originate from user code.")
      ]),
      bullet([
        bold("The projection is accessed through a named accessor on its owner. "),
        normal("For WindowingSubsystem, that accessor is windowing() on GUIEngine, available in both const and non-const overloads. Future subsystems follow the same convention.")
      ]),
      spacer(80),
      para([
        normal("The result is that "),
        mono("GUIEngine"),
        normal("\u2019s public API remains focused on lifecycle governance regardless of how many capabilities the engine internally hosts. Each capability has its own surface, and those surfaces are reached through named accessors rather than accumulating methods on the engine directly.")
      ]),
      spacer(160),
      rule(),

      // Lifetime
      h1("Lifetime of WindowingSubsystem"),
      para([
        mono("WindowingSubsystem"),
        normal(" is constructed by "),
        mono("GUIEngine"),
        normal(" as part of its own initialization, after the components it references have been constructed. Its lifetime is entirely bounded by the GUI engine that owns it.")
      ]),
      spacer(80),
      para([
        normal("Destruction order is non-negotiable: "),
        mono("WindowingSubsystem"),
        normal(" is destroyed "),
        bold("before"),
        normal(" "),
        mono("WindowDispatcher"),
        normal(" and "),
        mono("WindowCoordinator"),
        normal(". Since it holds non-owning references to both, allowing it to outlive either would leave it holding dangling references. "),
        mono("GUIEngine"),
        normal(" is responsible for enforcing this ordering as a matter of correctness.")
      ]),
      spacer(80),
      para([
        normal("The subsystem itself has no teardown logic beyond releasing its references. It does not wind down windows, it does not signal shutdown, and it does not participate in "),
        mono("GUIEngine"),
        normal("\u2019s teardown sequence. By the time teardown begins, its job is already done.")
      ]),
      spacer(160),
      rule(),

      // Two phases of use
      h1("Two Phases of Use"),
      para([
        mono("WindowingSubsystem"),
        normal(" serves user code across two distinct phases, both of which are part of its normal operational scope:")
      ]),
      spacer(80),

      h2("Pre-Commitment Registration"),
      para([
        normal("Before the "),
        mono("GUIEngine"),
        normal(" is committed to "),
        mono("AppProcess"),
        normal(", user code interacts with "),
        mono("WindowingSubsystem"),
        normal(" to register window factories. This is the process-level declaration of window intent \u2014 user code describes what kinds of windows the application has and the dispatch rules for each. The subsystem forwards these registrations to "),
        mono("WindowDispatcher"),
        normal(" on the user\u2019s behalf.")
      ]),
      spacer(80),
      para([
        normal("At commitment, the registration window closes. The factory set is effectively locked and no new registrations are accepted through this pathway. Post-commitment registration from within the running GUI layer is a deferred capability.")
      ]),
      spacer(120),

      h2("Runtime Window Operations"),
      para([
        normal("Once the mainloop is running, "),
        mono("WindowingSubsystem"),
        normal(" handles all user-initiated windowing operations: dispatching windows by factory ID, requesting subsidiary windows with a declared parent, querying live windows, and adding components to window envelopes by instance ID. Each of these operations orchestrates the appropriate collaboration between "),
        mono("WindowDispatcher"),
        normal(" and "),
        mono("WindowCoordinator"),
        normal(" without exposing either component directly to user code.")
      ]),
      spacer(160),
      rule(),

      // What it doesn't own
      h1("What WindowingSubsystem Deliberately Does Not Own"),
      para([italic("This boundary is just as important as what it does reference.")]),
      spacer(80),
      para("WindowingSubsystem does not own:"),
      bullet([mono("WindowDispatcher"), normal(" or "), mono("WindowCoordinator"), normal(" \u2014 those belong to GUIEngine")]),
      bullet("Any WindowEnvelope instances"),
      bullet("Any window lifecycle authority \u2014 it cannot initiate shutdown or teardown"),
      bullet([normal("Knowledge of "), mono("GUIEngine\u2019s"), normal(" internal operations \u2014 it only sees what user code asks of it")]),
      bullet("Any state of its own beyond its references to the underlying components"),
      spacer(160),
      rule(),

      // Error handling
      h1("Error Handling Philosophy"),
      para("WindowingSubsystem should:"),
      bullet("Refuse any operation that is illegal given the current phase \u2014 registering factories after commitment or dispatching windows before runtime activation are errors regardless of where the request originates"),
      bullet([normal("Propagate errors from "), mono("WindowDispatcher"), normal(" and "), mono("WindowCoordinator"), normal(" faithfully without swallowing or reinterpreting them")]),
      bullet("Never mask a constraint violation on behalf of user code \u2014 if the underlying component refuses the operation, the subsystem surfaces that refusal"),
      spacer(80),
      para([
        bold("Note: "),
        normal("The boundary between returned error codes and thrown exceptions follows the same open question as the rest of the library \u2014 deferred pending library-wide error handling strategy decisions.")
      ]),
      spacer(160),
      rule(),

      // Open questions
      h1("Open Questions and Deferred Decisions"),
      para("The following are known open questions that are intentionally deferred:"),
      spacer(80),
      bullet([
        bold("Full API surface: "),
        normal("The complete set of operations WindowingSubsystem exposes will grow as the windowing model matures. The operations described here \u2014 factory registration, window dispatch, subsidiary window parenting, live window queries, component access \u2014 represent the currently known set. Additional operations will be introduced as design work on the window layer progresses.")
      ]),
      bullet([
        bold("Post-commitment registration pathway: "),
        normal("The mechanism by which window factories may be registered from within the running GUI layer after engine commitment is a deferred capability. When that capability is designed, WindowingSubsystem is the natural surface through which it would be exposed.")
      ]),
      bullet([
        bold("Future subsystem projections: "),
        normal("WindowingSubsystem is the first instance of the subsystem projection pattern in GUIEngine. Additional subsystems \u2014 event routing, view management, and others \u2014 will follow the same pattern as the library grows. The precise set of future subsystems is not yet defined.")
      ]),
      bullet([
        bold("Const correctness of accessor overloads: "),
        normal("The precise split between what operations are available through the const versus non-const windowing() accessor has not been formally defined. Read-only query operations are natural candidates for the const overload. Mutating operations \u2014 registration, dispatch, component addition \u2014 require the non-const overload.")
      ]),
      bullet([
        bold("Error handling boundary: "),
        normal("Follows the same open question as the rest of the library. Deferred pending library-wide decisions.")
      ]),
      spacer(160),
      rule(),

      // Footer
      new Paragraph({
        children: [new TextRun({ text: "Chevron Library \u2014 Internal Design Documentation", font: FONT, size: 18, color: "AAAAAA", italics: true })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 160 }
      })
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/mnt/user-data/outputs/WindowingSubsystem_Class_Description.docx', buffer);
  console.log('Done');
});

