        children: [new TextRun({ text: "chevron::process::AppProcess", font: "Courier New", size: 40, bold: true, color: BLUE })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Class Design Description", font: FONT, size: 26, color: MID, italics: true })],
        spacing: { before: 0, after: 60 }
      }),
      rule(),
      spacer(80),

      // What AppProcess is — EXPANDED
      h1("What AppProcess Is"),
      para([
        mono("AppProcess"),
        normal(" is the "),
        bold("process-level coordinator"),
        normal(" that owns and decides "),
