const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, LevelFormat, BorderStyle, TableRow,
  TableCell, Table, WidthType, ShadingType, VerticalAlign
} = require('docx');
const fs = require('fs');

const FONT = "Arial";
const BLUE = "2E5FA3";
const DARK = "1A1A1A";
const MID  = "444444";
const LIGHT_BLUE = "EBF0F8";
const RULE_COLOR = "CCCCCC";

function rule() {
  return new Paragraph({
    children: [],
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: RULE_COLOR, space: 1 } },
    spacing: { before: 80, after: 160 }
  });
}

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, font: FONT, size: 36, bold: true, color: BLUE })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, font: FONT, size: 26, bold: true, color: DARK })]
  });
}

function para(runs, opts = {}) {
  const children = (typeof runs === 'string')
    ? [new TextRun({ text: runs, font: FONT, size: 22, color: DARK })]
    : runs;
  return new Paragraph({ children, spacing: { before: 80, after: 120 }, ...opts });
}

function bold(text, color = DARK) {
  return new TextRun({ text, font: FONT, size: 22, bold: true, color });
}

function normal(text) {
  return new TextRun({ text, font: FONT, size: 22, color: DARK });
}

function italic(text, color = MID) {
  return new TextRun({ text, font: FONT, size: 22, italics: true, color });
}

function mono(text) {
  return new TextRun({ text, font: "Courier New", size: 20, color: DARK });
}

function bullet(content, ref = "bullets") {
  const children = (typeof content === 'string')
    ? [new TextRun({ text: content, font: FONT, size: 22, color: DARK })]
    : content;
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    children,
    spacing: { before: 60, after: 60 }
  });
}

function blockquote(text) {
  return new Paragraph({
    children: [new TextRun({ text, font: FONT, size: 22, italics: true, color: "555555" })],
    indent: { left: 720 },
    border: { left: { style: BorderStyle.SINGLE, size: 12, color: BLUE, space: 10 } },
    spacing: { before: 120, after: 120 }
  });
}

function spacer(pts = 120) {
  return new Paragraph({ children: [], spacing: { before: 0, after: pts } });
}

function codeBlock(lines) {
  return lines.map((line, i) => new Paragraph({
    children: [new TextRun({ text: line, font: "Courier New", size: 20, color: "2E5FA3" })],
    spacing: { before: i === 0 ? 100 : 0, after: i === lines.length - 1 ? 100 : 0 },
    indent: { left: 720 },
    shading: { val: "clear", fill: "F4F4F4" }
  }));
}

function headerCell(text) {
  return new TableCell({
    shading: { fill: BLUE, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({
      children: [new TextRun({ text, font: FONT, size: 20, bold: true, color: "FFFFFF" })]
    })]
  });
}

function dataCell(content, shaded = false) {
  const children = (typeof content === 'string')
    ? [new Paragraph({ children: [new TextRun({ text: content, font: FONT, size: 20, color: DARK })] })]
    : content;
  return new TableCell({
    shading: { fill: shaded ? "F4F7FC" : "FFFFFF", type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    verticalAlign: VerticalAlign.CENTER,
    children
  });
}

function monoCell(text, shaded = false) {
  return new TableCell({
    shading: { fill: shaded ? "F4F7FC" : "FFFFFF", type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({
      children: [new TextRun({ text, font: "Courier New", size: 19, color: BLUE })]
    })]
  });
}

const border = { style: BorderStyle.SINGLE, size: 1, color: "CCCCCC" };
const borders = { top: border, bottom: border, left: border, right: border };

const doc = new Document({
  styles: {
    default: { document: { run: { font: FONT, size: 22 } } },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: FONT, color: BLUE },
        paragraph: { spacing: { before: 360, after: 160 }, outlineLevel: 0 }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: FONT, color: DARK },
        paragraph: { spacing: { before: 280, after: 120 }, outlineLevel: 1 }
      }
    ]
  },
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      },
      {
        reference: "numbers",
        levels: [{
          level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      },
      {
        reference: "subbullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u25E6", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 1080, hanging: 360 } } }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [

      // Title block
      new Paragraph({
        children: [new TextRun({ text: "Application Process Layer", font: FONT, size: 52, bold: true, color: BLUE })],
        spacing: { before: 0, after: 60 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Architectural Outline", font: FONT, size: 32, color: MID, italics: true })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Chevron Library \u2014 Internal Design Documentation", font: FONT, size: 20, color: "AAAAAA", italics: true })],
        spacing: { before: 0, after: 60 }
      }),
      rule(),
      spacer(80),

      // ─── SECTION 1 ───────────────────────────────────────────────
      h1("1. What the Application Process Layer Is"),
      para([
        normal("The "),
        bold("Application Process Layer"),
        normal(" is the foundational stratum of Chevron\u2019s architecture. It owns everything required to bring a GUI application into existence, keep it running correctly, and tear it down cleanly. Every class in this layer exists to solve a specific, non-overlapping problem in that lifecycle — and together they form a complete, self-consistent system that application code can rely on without having to manage any of the underlying mechanics manually.")
      ]),
      spacer(80),
      para([
        normal("At its core, the process layer answers one question on behalf of every Chevron-powered application:")
      ]),
      blockquote("\u201CHow does a GUI application come into existence, govern its windows, and exit correctly?\u201D"),
      para([
        normal("Without this layer, the answers to that question would be scattered across user code. Someone would need to manually sequence the GUI framework\u2019s startup, enforce lifecycle invariants, create a disciplined window creation authority, track live windows, manage parent-child window relationships, and ensure that shutdown always unwinds cleanly regardless of how it was triggered. Every application that chose not to solve these problems carefully would be subtly broken in ways that are difficult to diagnose and even harder to fix.")
      ]),
      spacer(80),
      para([
        normal("The process layer centralizes all of that. It is not concerned with what the application "),
        italic("does"),
        normal(" — that is user code\u2019s domain. It is concerned with the non-negotiable structural mechanics that any well-formed GUI application must get right. Chevron\u2019s core promise — "),
        italic("\u201Cif the application is running, it is running correctly\u201D"),
        normal(" — is enforced entirely within this layer.")
      ]),
      spacer(80),
      para([
        normal("The layer is composed of nine classes, each with a precisely defined responsibility and precisely defined boundaries. No class in the layer does more than its responsibility requires. No class reaches into another\u2019s domain. The result is a system where each part is independently understandable, the interactions between parts are explicit and documented, and the whole is more trustworthy than the sum of its parts.")
      ]),
      spacer(160),
      rule(),

      // ─── SECTION 2 ───────────────────────────────────────────────
      h1("2. The Three-Tier Lifetime Hierarchy"),
      para([
        normal("The entire process layer is organized around a single governing principle: "),
        bold("lifetime nesting"),
        normal(". Every class in the layer belongs to one of three lifetime tiers, and nothing at a given tier may exist before the tier above it has been established, or outlive the tier above it when it tears down.")
      ]),
      spacer(80),
      ...codeBlock([
        "Process lifetime   ->   AppProcess",
        "GUI lifetime       ->   GUIEngine",
        "                          |- WindowDispatcher      (creation authority)",
        "                          |- WindowCoordinator     (lifetime authority)",
        "                          |    |- WindowHierarchy  (relationship graph)",
        "                          |- WindowingSubsystem    (user-facing projection)",
        "Window lifetime    ->   WindowEnvelope",
        "                          |- WindowComponentStore  (PWI components)",
      ]),
      spacer(120),
      para([
        bold("Process lifetime"),
        normal(" is the outermost tier. "),
        mono("AppProcess"),
        normal(" is the only class at this level. It exists for the entire duration of the application, from the first meaningful object construction to the last cleanup before exit. Everything else in the layer lives within the boundary it establishes.")
      ]),
      spacer(80),
      para([
        bold("GUI lifetime"),
        normal(" is the middle tier. "),
        mono("GUIEngine"),
        normal(" and all the infrastructure it owns — "),
        mono("WindowDispatcher"),
        normal(", "),
        mono("WindowCoordinator"),
        normal(", "),
        mono("WindowHierarchy"),
        normal(", and "),
        mono("WindowingSubsystem"),
        normal(" — exist only while the GUI framework is active. None of these classes may be used before "),
        mono("GUIEngine"),
        normal(" is initialized, and none may outlive "),
        mono("GUIEngine\u2019s"),
        normal(" shutdown. The GUI tier is nested entirely within the process tier.")
      ]),
      spacer(80),
      para([
        bold("Window lifetime"),
        normal(" is the innermost tier. "),
        mono("WindowEnvelope"),
        normal(" and its owned "),
        mono("WindowComponentStore"),
        normal(" exist only while a specific window is alive within the running GUI. Windows may come and go during the GUI\u2019s lifetime, but no window envelope may exist before the GUI engine is active or outlive it. The window tier is nested entirely within the GUI tier.")
      ]),
      spacer(80),
      para([
        normal("This nesting is not a convention or a guideline — it is enforced structurally. "),
        mono("AppProcess"),
        normal(" owns "),
        mono("GUIEngine"),
        normal(". "),
        mono("GUIEngine"),
        normal(" owns "),
        mono("WindowCoordinator"),
        normal(", which owns every live "),
        mono("WindowEnvelope"),
        normal(". Destruction flows outward to inward: process tier tears down last, window tier tears down first. No object at any tier can outlive the tier above it because ownership prevents it.")
      ]),
      spacer(160),
      rule(),

      // ─── SECTION 3 ───────────────────────────────────────────────
      h1("3. The Classes at a Glance"),
      para([
        normal("The following table provides a concise orientation to each class in the process layer. Individual class description documents provide full detail on each entry.")
      ]),
      spacer(80),
      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [2000, 1400, 3360, 2600],
        rows: [
          new TableRow({
            tableHeader: true,
            children: [
              headerCell("Class"),
              headerCell("Lifetime Tier"),
              headerCell("Core Responsibility"),
              headerCell("Owns / Produces"),
            ]
          }),
          new TableRow({ children: [
            monoCell("AppProcess", false),
            dataCell("Process", false),
            dataCell("Owns the application lifecycle. Drives GUIEngine through a strictly sequenced initialization and shutdown. Enforces lifecycle invariants.", false),
            dataCell("Owns exactly one GUIEngine instance.", false),
          ]}),
          new TableRow({ children: [
            monoCell("GUIEngine", true),
            dataCell("GUI", true),
            dataCell("Owns and controls the GUI framework environment. Owns all GUI-scoped infrastructure. Enforces the invariant that no GUI-bound object exists outside of GUI lifetime.", true),
            dataCell("Owns WindowDispatcher, WindowCoordinator, WindowingSubsystem. Owns all WindowEnvelope instances indirectly.", true),
          ]}),
          new TableRow({ children: [
            monoCell("WindowDispatcher", false),
            dataCell("GUI", false),
            dataCell("The sole authority for window creation. Accepts WindowFactory registrations, validates dispatch constraints, executes factory callables, and hands off the result.", false),
            dataCell("Stores WindowFactory instances. Produces WindowEnvelope instances at dispatch time.", false),
          ]}),
          new TableRow({ children: [
            monoCell("WindowFactory", true),
            dataCell("GUI (stored)", true),
            dataCell("Bundles a factory callable with its descriptor flags. Gives the dispatcher everything it needs to decide whether and how to create a window.", true),
            dataCell("Carries a factory callable and a descriptor bitmask. Assigned a sequential factory ID by the dispatcher.", true),
          ]}),
          new TableRow({ children: [
            monoCell("WindowCoordinator", false),
            dataCell("GUI", false),
            dataCell("The lifetime authority for all live window envelopes. Receives, tracks, and eventually winds down every WindowEnvelope. Owns the window relationship graph.", false),
            dataCell("Owns all live WindowEnvelope instances. Owns WindowHierarchy.", false),
          ]}),
          new TableRow({ children: [
            monoCell("WindowHierarchy", true),
            dataCell("GUI (sub-component)", true),
            dataCell("Maintains the parent-child relationship graph between live window envelopes. Provides safe teardown traversal order.", true),
            dataCell("Owns the relationship graph data structure. Produces traversal order on request.", true),
          ]}),
          new TableRow({ children: [
            monoCell("WindowEnvelope", false),
            dataCell("Window", false),
            dataCell("The per-window infrastructure container. Bundles the raw backend window handle with Chevron-assigned identity and the window's component store.", false),
            dataCell("Holds the backend window handle. Owns WindowComponentStore.", false),
          ]}),
          new TableRow({ children: [
            monoCell("WindowInitContext", true),
            dataCell("Transient", true),
            dataCell("The dispatch-time initialization token. Authorizes and parameterizes the construction of a WindowEnvelope. Carries the parent handle for subsidiary window dispatches.", true),
            dataCell("Transient — exists for the duration of one factory call only. Carries no persistent state.", true),
          ]}),
          new TableRow({ children: [
            monoCell("WindowingSubsystem", false),
            dataCell("GUI", false),
            dataCell("The public-facing projection of GUIEngine\u2019s windowing capability. Orchestrates WindowDispatcher and WindowCoordinator on behalf of user code.", false),
            dataCell("Holds non-owning references to WindowDispatcher and WindowCoordinator. Does not own any infrastructure.", false),
          ]}),
        ]
      }),
      spacer(160),
      rule(),

      // ─── SECTION 4 ───────────────────────────────────────────────
      h1("4. The Lifecycle Walkthrough"),
      para([
        normal("The best way to understand how the process layer\u2019s classes work together is to follow a complete application lifecycle from the first line of user code to the final exit. What follows is that walkthrough — each class appearing at the moment it becomes relevant, its role in that moment described clearly.")
      ]),
      spacer(120),

      h2("Phase 1 — Process Setup"),
      para([
        normal("The user constructs an "),
        mono("AppProcess"),
        normal(" instance near the entry point. This is the first meaningful object in the system. It owns nothing yet — no engine, no windows — but it establishes the process-level authority that everything else will answer to. The application\u2019s lifecycle has begun.")
      ]),
      spacer(80),
      para([
        normal("The user then constructs a concrete "),
        mono("GUIEngine"),
        normal(" implementation — for example, "),
        mono("chevron::wx::Engine"),
        normal(". At this point the GUI framework has not been touched. No global state has been initialized. The engine exists as a configured object, ready to be committed. Configuration is still mutable here.")
      ]),
      spacer(80),
      para([
        normal("Before committing the engine, the user interacts with "),
        mono("WindowingSubsystem"),
        normal(" through "),
        mono("engine.windowing()"),
        normal(" to register their window factories. For each kind of window the application will have, the user constructs a "),
        mono("WindowFactory"),
        normal(" — pairing a factory callable with a descriptor bitmask — and submits it. "),
        mono("WindowDispatcher"),
        normal(" assigns each factory a sequential ID and stores it. The IDs are returned to the user, who may capture them as named constants for later use. This is the process-level declaration of window intent. No windows exist yet. No GUI work has occurred. These registrations are purely declarative.")
      ]),
      spacer(80),
      para([
        normal("The user commits the engine to "),
        mono("AppProcess"),
        normal(". Ownership transfers. Configuration is locked. The engine is now the chosen backend for the lifetime of the process. The process-level registration window closes — no new factories may be registered through this pathway until a post-commitment registration capability is designed.")
      ]),
      spacer(120),

      h2("Phase 2 \u2014 GUI Initialization"),
      para([
        normal("AppProcess"),
        normal(" instructs "),
        mono("GUIEngine"),
        normal(" to initialize. This is the moment the GUI framework comes alive. The framework\u2019s application object is created, environment assumptions are validated, and internal subsystems are prepared. "),
        mono("WindowDispatcher"),
        normal(", "),
        mono("WindowCoordinator"),
        normal(", "),
        mono("WindowHierarchy"),
        normal(", and "),
        mono("WindowingSubsystem"),
        normal(" are all already constructed as part of "),
        mono("GUIEngine"),
        normal(" \u2014 they have been ready since engine construction. The mainloop has not started. Windows do not exist yet.")
      ]),
      spacer(80),
      para([
        normal("If initialization fails at this point, no mainloop starts, no windows are created, and the application can exit cleanly. "),
        mono("AppProcess"),
        normal(" is informed and handles the error path. The system never reaches a half-alive state.")
      ]),
      spacer(120),

      h2("Phase 3 \u2014 Runtime Start"),
      para([
        normal("AppProcess"),
        normal(" calls "),
        mono("mainloopEntry()"),
        normal(", which honors the call by invoking "),
        mono("runtime()"),
        normal(" on the engine. This is the point of no return. The GUI engine becomes fully active.")
      ]),
      spacer(80),
      para([
        normal("The first action inside the running engine is the materialization of the startup window. "),
        mono("WindowDispatcher"),
        normal(" identifies the appropriate factory \u2014 either the one carrying the root window flag, or the first registered factory if no flag was set \u2014 and fires it. The factory callable receives a "),
        mono("WindowInitContext"),
        normal(" assembled by "),
        mono("GUIEngine"),
        normal(" at dispatch time. The context carries Chevron\u2019s internal bootstrapping data and, for subsidiary windows, the parent window handle. The factory constructs the backend window and passes it along with the context to Chevron\u2019s envelope construction function.")
      ]),
      spacer(80),
      para([
        normal("Chevron constructs a "),
        mono("WindowEnvelope"),
        normal(", assigns it an instance ID, and populates its "),
        mono("WindowComponentStore"),
        normal(" with the base per-window infrastructure (PWI) components unconditionally. The envelope is returned to "),
        mono("WindowDispatcher"),
        normal(", which immediately transfers ownership to "),
        mono("WindowCoordinator"),
        normal(". The coordinator registers the envelope in its registry, records its factory ID, and if applicable records its parent-child relationship in "),
        mono("WindowHierarchy"),
        normal(". The "),
        mono("WindowInitContext"),
        normal(" is consumed and destroyed. The window is now live.")
      ]),
      spacer(80),
      para([
        normal("The mainloop enters. "),
        mono("mainloopEntry()"),
        normal(" blocks. Control flow is inside the GUI framework. The application is running.")
      ]),
      spacer(120),

      h2("Phase 4 \u2014 Active Runtime"),
      para([
        normal("During normal operation, dispatch requests may arrive at any time from user interaction, application logic, or internal triggers. Each dispatch request flows through "),
        mono("WindowingSubsystem"),
        normal(" to "),
        mono("WindowDispatcher"),
        normal(". The dispatcher consults the relevant "),
        mono("WindowFactory\u2019s"),
        normal(" descriptor to verify constraints \u2014 single-instance checks query "),
        mono("WindowCoordinator"),
        normal(" by factory ID \u2014 and if all constraints are satisfied, fires the factory. The resulting envelope is transferred to "),
        mono("WindowCoordinator"),
        normal(" and the coordinator updates its registry and "),
        mono("WindowHierarchy"),
        normal(" accordingly.")
      ]),
      spacer(80),
      para([
        normal("WindowCoordinator"),
        normal(" watches the full population of live envelopes at all times. When a window closes, its envelope leaves the registry. If the last envelope leaves, the coordinator surfaces a last-window-closed event to "),
        mono("GUIEngine"),
        normal(", which may in turn signal "),
        mono("AppProcess"),
        normal(" to begin shutdown. The coordinator does not initiate shutdown itself \u2014 it observes, records, and notifies. The decision of what to do belongs to "),
        mono("GUIEngine"),
        normal(" and ultimately to "),
        mono("AppProcess"),
        normal(".")
      ]),
      spacer(120),

      h2("Phase 5 \u2014 Shutdown and Teardown"),
      para([
        normal("Shutdown may be initiated from three sources: user code calling shutdown explicitly, the GUI framework initiating exit when the root window closes, or "),
        mono("AppProcess"),
        normal(" requesting it programmatically. All three paths converge on "),
        mono("GUIEngine"),
        normal(", which coordinates the teardown sequence. Calling shutdown twice is always safe.")
      ]),
      spacer(80),
      para([
        normal("The mainloop stops. "),
        mono("WindowCoordinator"),
        normal(" asks "),
        mono("WindowHierarchy"),
        normal(" for a safe teardown traversal order \u2014 children before parents, windows with no registered parent addressed last. Each envelope is wound down in that order: its "),
        mono("WindowComponentStore"),
        normal(" components are destroyed in reverse registration order, the backend window handle is released last, and the envelope is removed from the coordinator\u2019s registry and from "),
        mono("WindowHierarchy"),
        normal(".")
      ]),
      spacer(80),
      para([
        normal("Once all envelopes are gone, "),
        mono("WindowingSubsystem"),
        normal(" is destroyed \u2014 before the components it references, since it holds non-owning references to "),
        mono("WindowDispatcher"),
        normal(" and "),
        mono("WindowCoordinator"),
        normal(" and must not outlive either. The GUI framework is then deinitialized. Control returns to "),
        mono("AppProcess"),
        normal(", which completes its own cleanup and returns an exit code to the process.")
      ]),
      spacer(160),
      rule(),

      // ─── SECTION 5 ───────────────────────────────────────────────
      h1("5. Ownership and Authority"),
      para([
        normal("Understanding who owns what and who is authoritative over what is essential for reasoning about correctness in the process layer. These are not informal conventions \u2014 they are structural properties enforced through the design.")
      ]),
      spacer(120),

      h2("The Ownership Chain"),
      para("Ownership in the process layer is hierarchical and unambiguous:"),
      spacer(80),
      bullet([mono("AppProcess"), normal(" owns exactly one "), mono("GUIEngine"), normal(" instance for the lifetime of the process.")]),
      bullet([mono("GUIEngine"), normal(" owns "), mono("WindowDispatcher"), normal(", "), mono("WindowCoordinator"), normal(", and "), mono("WindowingSubsystem"), normal(" at the base class level. These are written once and shared across all concrete backend implementations.")]),
      bullet([mono("WindowCoordinator"), normal(" owns all live "), mono("WindowEnvelope"), normal(" instances and owns "), mono("WindowHierarchy"), normal(".")]),
      bullet([mono("WindowEnvelope"), normal(" owns the raw backend window handle and its "), mono("WindowComponentStore"), normal(".")]),
      bullet([mono("WindowingSubsystem"), normal(" holds non-owning references to "), mono("WindowDispatcher"), normal(" and "), mono("WindowCoordinator"), normal(". It does not own them. It is destroyed before they are.")]),
      bullet([mono("WindowFactory"), normal(" instances are stored inside "), mono("WindowDispatcher"), normal(". The dispatcher owns them.")]),
      bullet([mono("WindowInitContext"), normal(" is transient — assembled by "), mono("GUIEngine"), normal(" at dispatch time, consumed during factory execution, and gone.")]),
      spacer(120),

      h2("The Authority Split"),
      para([
        normal("Authority in the process layer is separated from ownership in meaningful ways. The most important split is between creation authority and lifetime authority in the windowing system.")
      ]),
      spacer(80),
      para([
        bold("WindowDispatcher"),
        normal(" is the "),
        bold("creation authority"),
        normal(". It decides whether a window is allowed to exist right now and, if so, executes the factory that produces it. Once a window has been created and handed off, the dispatcher has no further authority over it. It is done.")
      ]),
      spacer(80),
      para([
        bold("WindowCoordinator"),
        normal(" is the "),
        bold("lifetime authority"),
        normal(". It owns every live envelope from the moment the dispatcher hands one over. It tracks identities, manages relationships through "),
        mono("WindowHierarchy"),
        normal(", detects lifecycle events, and governs teardown. It knows everything about what windows currently exist. The dispatcher knows nothing about this.")
      ]),
      spacer(80),
      para([
        normal("This split is deliberate and non-negotiable. Combining creation and lifetime authority into a single class would produce an unmanageable god object. Separating them gives each class a clean, focused responsibility and makes both independently testable and understandable.")
      ]),
      spacer(120),

      h2("The Dependency Direction"),
      para([
        normal("Dependencies in the process layer flow in one direction: inward. "),
        mono("AppProcess"),
        normal(" depends on "),
        mono("GUIEngine"),
        normal(" through a polymorphic interface. "),
        mono("GUIEngine"),
        normal(" depends on its owned components. "),
        mono("WindowDispatcher"),
        normal(" depends on "),
        mono("WindowCoordinator"),
        normal(" through a narrow query interface for single-instance checks — but "),
        mono("WindowCoordinator"),
        normal(" does not depend on "),
        mono("WindowDispatcher"),
        normal(". This one-way dependency is intentional. The coordinator is a full participant in the window lifecycle. The dispatcher is a mechanism that fires and steps aside.")
      ]),
      spacer(80),
      para([
        mono("WindowingSubsystem"),
        normal(" depends on both "),
        mono("WindowDispatcher"),
        normal(" and "),
        mono("WindowCoordinator"),
        normal(" through non-owning references. Neither of those components depends on "),
        mono("WindowingSubsystem"),
        normal(". The subsystem is a projection over them, not a participant in their internal operations.")
      ]),
      spacer(160),
      rule(),

      // ─── SECTION 6 ───────────────────────────────────────────────
      h1("6. The Windowing Subsystem \u2014 A Closer Look"),
      para([
        normal("Of the nine classes in the process layer, "),
        mono("WindowingSubsystem"),
        normal(" has the most unusual character: it owns nothing, it enforces nothing independently, and it has no lifecycle of its own beyond its references. Yet it is the most important class from user code\u2019s perspective, because it is the only windowing surface user code ever sees.")
      ]),
      spacer(80),
      para([
        normal("Understanding "),
        mono("WindowingSubsystem"),
        normal(" requires understanding the problem it solves. As "),
        mono("GUIEngine\u2019s"),
        normal(" windowing capabilities grow, every user-facing windowing operation \u2014 factory registration, window dispatch, live window queries, component access, subsidiary window parenting \u2014 would naturally accumulate on "),
        mono("GUIEngine\u2019s"),
        normal(" own API. None of these operations belong to "),
        mono("GUIEngine\u2019s"),
        normal(" actual identity, which is lifecycle governance. Letting them accumulate there produces a class that is simultaneously a lifecycle authority and an operational windowing API \u2014 two responsibilities that have no business sharing a surface.")
      ]),
      spacer(80),
      para([
        mono("WindowingSubsystem"),
        normal(" solves this by being the coherent home for those operations. "),
        mono("GUIEngine\u2019s"),
        normal(" API stays focused on initialization, mainloop control, and shutdown. Everything a user needs to do with windows flows through "),
        mono("engine.windowing()"),
        normal(" instead. The subsystem holds non-owning references to "),
        mono("WindowDispatcher"),
        normal(" and "),
        mono("WindowCoordinator"),
        normal(" and orchestrates their collaboration on behalf of user code.")
      ]),
      spacer(80),
      para([
        normal("The key property that makes this work without creating confusion is that "),
        mono("WindowDispatcher"),
        normal(" and "),
        mono("WindowCoordinator"),
        normal(" retain their full independence. They continue to collaborate directly for internal purposes \u2014 the single-instance query, the envelope handoff, last-window-close notification \u2014 without "),
        mono("WindowingSubsystem"),
        normal(" being involved. The subsystem handles only operations that originate from user code. Internal operations bypass it entirely.")
      ]),
      spacer(80),
      para([
        normal("This is the first instance of an explicit, repeatable pattern in Chevron: the "),
        bold("subsystem projection pattern"),
        normal(". Whenever a cluster of internal components together form a coherent user-facing capability, a dedicated projection class surfaces that capability without those components surrendering their independence. "),
        mono("WindowingSubsystem"),
        normal(" is the template. As the library grows, additional subsystems \u2014 event routing, memory management, threading \u2014 will follow the same pattern.")
      ]),
      spacer(160),
      rule(),

      // ─── SECTION 7 ───────────────────────────────────────────────
      h1("7. Layer Boundaries \u2014 Scope and Responsibility"),
      para([
        normal("A layer\u2019s boundaries are defined by its purpose, not by an arbitrary list of exclusions. Understanding where the process layer ends requires understanding what it is fundamentally trying to do \u2014 and then recognizing that everything outside that purpose belongs somewhere else.")
      ]),
      spacer(120),

      h2("The Boundary Defined"),
      para([
        normal("The process layer\u2019s purpose is precisely this: "),
        bold("to own the structural mechanics that make a GUI application well-formed"),
        normal(". Well-formed means the application starts correctly, runs without violating its own invariants, and exits cleanly regardless of how shutdown is triggered. The layer concerns itself with the question of "),
        italic("how"),
        normal(" the application is structured and governed, not "),
        italic("what"),
        normal(" the application does.")
      ]),
      spacer(80),
      para([
        normal("From this purpose, the boundary draws itself. A concern belongs in the process layer if and only if it is a universal structural mechanic that every well-formed GUI application under Chevron must have, regardless of its domain, regardless of which GUI framework it uses, and regardless of what it is trying to accomplish for its users. It must be the kind of thing that, if left to user code, would be either consistently gotten wrong or consistently reimplemented with slight variations that introduce subtle differences in correctness.")
      ]),
      spacer(80),
      para([
        normal("Everything that passes that test is in the layer. Everything that fails it is not."),
      ]),
      spacer(120),

      h2("Where the Boundary Sits"),
      para([
        normal("Applying that definition makes the boundary precise:")
      ]),
      spacer(80),
      para([
        bold("Inside the boundary \u2014 structural application mechanics:"),
      ]),
      bullet([normal("Application lifetime ownership and sequencing \u2014 this is universal to every application and must be correct")]),
      bullet([normal("GUI framework environment governance \u2014 frameworks are environments with global state and threading requirements that must be tamed")]),
      bullet([normal("Window creation authority and dispatch policy \u2014 ad-hoc window creation scatters responsibility and produces inconsistent behavior")]),
      bullet([normal("Live window tracking and lifetime management \u2014 something must own windows and know when they are gone")]),
      bullet([normal("Window relationship tracking \u2014 parent-child relationships affect teardown ordering and must be recorded")]),
      bullet([normal("Per-window infrastructure provisioning \u2014 the structural scaffolding every window needs (identity, memory, logging context, view machinery)"])),
      bullet([normal("Lifecycle sequencing and invariant enforcement \u2014 the guarantees that prevent the system from ever reaching a half-alive state")]),
      spacer(80),
      para([
        bold("Outside the boundary \u2014 application domain and framework surface:"),
      ]),
      bullet([normal("Widgets, layout, and visual composition \u2014 these are the framework\u2019s domain and vary by framework. Chevron has no opinion on them and deliberately provides no abstraction over them.")]),
      bullet([normal("Event handling and routing beyond lifecycle signals \u2014 user interaction events are application logic, not structural mechanics. Chevron\u2019s future EventSubsystem will provide infrastructure here, but it is a separate concern.")]),
      bullet([normal("Business logic and domain models \u2014 what the application does for its users is entirely outside Chevron\u2019s scope")]),
      bullet([normal("Cross-GUI-framework portability at the user-code level \u2014 Chevron does not provide a unified GUI API. User code is written against the chosen framework directly.")]),
      bullet([normal("Non-GUI services \u2014 networking, file I/O, database access, and similar concerns are not GUI application infrastructure")]),
      spacer(120),

      h2("Why the Boundary Must Be Held"),
      para([
        normal("The process layer\u2019s value comes precisely from its focus. A layer that owns everything owns nothing well. By confining itself to structural application mechanics, the process layer can make strong correctness guarantees about everything within its boundary. The moment it takes on concerns outside that boundary \u2014 trying to abstract widgets, providing convenience wrappers for events, or touching domain logic \u2014 those guarantees erode because the scope has grown beyond what can be reasoned about cleanly.")
      ]),
      spacer(80),
      para([
        normal("Chevron\u2019s philosophy is that it is application infrastructure, not a GUI framework abstraction. The process layer is the clearest expression of that philosophy in concrete form. Every class in it exists because a well-formed GUI application cannot be built without what that class provides. None of them exist because they make GUI programming more convenient in a general sense. That distinction \u2014 "),
        italic("necessary structural mechanics"),
        normal(" versus "),
        italic("convenient framework wrappers"),
        normal(" \u2014 is the boundary, stated in its most essential form.")
      ]),
      spacer(160),
      rule(),

      // Footer
      new Paragraph({
        children: [new TextRun({ text: "Chevron Library \u2014 Internal Design Documentation", font: FONT, size: 18, color: "AAAAAA", italics: true })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 160 }
      })
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/mnt/user-data/outputs/AppProcessLayer_Outline.docx', buffer);
  console.log('Done');
});

display_content.json_block:
{"language": "javascript", "code": "const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, LevelFormat, BorderStyle, TableRow,
  TableCell, Table, WidthType, ShadingType, VerticalAlign
} = require('docx');
const fs = require('fs');

const FONT = "Arial";
const BLUE = "2E5FA3";
const DARK = "1A1A1A";
const MID  = "444444";
const LIGHT_BLUE = "EBF0F8";
const RULE_COLOR = "CCCCCC";

function rule() {
  return new Paragraph({
    children: [],
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: RULE_COLOR, space: 1 } },
    spacing: { before: 80, after: 160 }
  });
}

function h1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    children: [new TextRun({ text, font: FONT, size: 36, bold: true, color: BLUE })]
  });
}

function h2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    children: [new TextRun({ text, font: FONT, size: 26, bold: true, color: DARK })]
  });
}

function para(runs, opts = {}) {
  const children = (typeof runs === 'string')
    ? [new TextRun({ text: runs, font: FONT, size: 22, color: DARK })]
    : runs;
  return new Paragraph({ children, spacing: { before: 80, after: 120 }, ...opts });
}

function bold(text, color = DARK) {
  return new TextRun({ text, font: FONT, size: 22, bold: true, color });
}

function normal(text) {
  return new TextRun({ text, font: FONT, size: 22, color: DARK });
}

function italic(text, color = MID) {
  return new TextRun({ text, font: FONT, size: 22, italics: true, color });
}

function mono(text) {
  return new TextRun({ text, font: "Courier New", size: 20, color: DARK });
}

function bullet(content, ref = "bullets") {
  const children = (typeof content === 'string')
    ? [new TextRun({ text: content, font: FONT, size: 22, color: DARK })]
    : content;
  return new Paragraph({
    numbering: { reference: ref, level: 0 },
    children,
    spacing: { before: 60, after: 60 }
  });
}

function blockquote(text) {
  return new Paragraph({
    children: [new TextRun({ text, font: FONT, size: 22, italics: true, color: "555555" })],
    indent: { left: 720 },
    border: { left: { style: BorderStyle.SINGLE, size: 12, color: BLUE, space: 10 } },
    spacing: { before: 120, after: 120 }
  });
}

function spacer(pts = 120) {
  return new Paragraph({ children: [], spacing: { before: 0, after: pts } });
}

function codeBlock(lines) {
  return lines.map((line, i) => new Paragraph({
    children: [new TextRun({ text: line, font: "Courier New", size: 20, color: "2E5FA3" })],
    spacing: { before: i === 0 ? 100 : 0, after: i === lines.length - 1 ? 100 : 0 },
    indent: { left: 720 },
    shading: { val: "clear", fill: "F4F4F4" }
  }));
}

function headerCell(text) {
  return new TableCell({
    shading: { fill: BLUE, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({
      children: [new TextRun({ text, font: FONT, size: 20, bold: true, color: "FFFFFF" })]
    })]
  });
}

function dataCell(content, shaded = false) {
  const children = (typeof content === 'string')
    ? [new Paragraph({ children: [new TextRun({ text: content, font: FONT, size: 20, color: DARK })] })]
    : content;
  return new TableCell({
    shading: { fill: shaded ? "F4F7FC" : "FFFFFF", type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    verticalAlign: VerticalAlign.CENTER,
    children
  });
}

function monoCell(text, shaded = false) {
  return new TableCell({
    shading: { fill: shaded ? "F4F7FC" : "FFFFFF", type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({
      children: [new TextRun({ text, font: "Courier New", size: 19, color: BLUE })]
    })]
  });
}

const border = { style: BorderStyle.SINGLE, size: 1, color: "CCCCCC" };
const borders = { top: border, bottom: border, left: border, right: border };

const doc = new Document({
  styles: {
    default: { document: { run: { font: FONT, size: 22 } } },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: FONT, color: BLUE },
        paragraph: { spacing: { before: 360, after: 160 }, outlineLevel: 0 }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: FONT, color: DARK },
        paragraph: { spacing: { before: 280, after: 120 }, outlineLevel: 1 }
      }
    ]
  },
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      },
      {
        reference: "numbers",
        levels: [{
          level: 0, format: LevelFormat.DECIMAL, text: "%1.", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      },
      {
        reference: "subbullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u25E6", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 1080, hanging: 360 } } }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
      }
    },
    children: [

      // Title block
      new Paragraph({
        children: [new TextRun({ text: "Application Process Layer", font: FONT, size: 52, bold: true, color: BLUE })],
        spacing: { before: 0, after: 60 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Architectural Outline", font: FONT, size: 32, color: MID, italics: true })],
        spacing: { before: 0, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ text: "Chevron Library \u2014 Internal Design Documentation", font: FONT, size: 20, color: "AAAAAA", italics: true })],
        spacing: { before: 0, after: 60 }
      }),
      rule(),
      spacer(80),

      // ─── SECTION 1 ───────────────────────────────────────────────
      h1("1. What the Application Process Layer Is"),
      para([
        normal("The "),
        bold("Application Process Layer"),
        normal(" is the foundational stratum of Chevron\u2019s architecture. It owns everything required to bring a GUI application into existence, keep it running correctly, and tear it down cleanly. Every class in this layer exists to solve a specific, non-overlapping problem in that lifecycle — and together they form a complete, self-consistent system that application code can rely on without having to manage any of the underlying mechanics manually.")
      ]),
      spacer(80),
      para([
        normal("At its core, the process layer answers one question on behalf of every Chevron-powered application:")
      ]),
      blockquote("\u201CHow does a GUI application come into existence, govern its windows, and exit correctly?\u201D"),
      para([
        normal("Without this layer, the answers to that question would be scattered across user code. Someone would need to manually sequence the GUI framework\u2019s startup, enforce lifecycle invariants, create a disciplined window creation authority, track live windows, manage parent-child window relationships, and ensure that shutdown always unwinds cleanly regardless of how it was triggered. Every application that chose not to solve these problems carefully would be subtly broken in ways that are difficult to diagnose and even harder to fix.")
      ]),
      spacer(80),
      para([
        normal("The process layer centralizes all of that. It is not concerned with what the application "),
        italic("does"),
        normal(" — that is user code\u2019s domain. It is concerned with the non-negotiable structural mechanics that any well-formed GUI application must get right. Chevron\u2019s core promise — "),
        italic("\u201Cif the application is running, it is running correctly\u201D"),
        normal(" — is enforced entirely within this layer.")
      ]),
      spacer(80),
      para([
        normal("The layer is composed of nine classes, each with a precisely defined responsibility and precisely defined boundaries. No class in the layer does more than its responsibility requires. No class reaches into another\u2019s domain. The result is a system where each part is independently understandable, the interactions between parts are explicit and documented, and the whole is more trustworthy than the sum of its parts.")
      ]),
      spacer(160),
      rule(),

      // ─── SECTION 2 ───────────────────────────────────────────────
      h1("2. The Three-Tier Lifetime Hierarchy"),
      para([
        normal("The entire process layer is organized around a single governing principle: "),
        bold("lifetime nesting"),
        normal(". Every class in the layer belongs to one of three lifetime tiers, and nothing at a given tier may exist before the tier above it has been established, or outlive the tier above it when it tears down.")
      ]),
      spacer(80),
      ...codeBlock([
        "Process lifetime   ->   AppProcess",
        "GUI lifetime       ->   GUIEngine",
        "                          |- WindowDispatcher      (creation authority)",
        "                          |- WindowCoordinator     (lifetime authority)",
        "                          |    |- WindowHierarchy  (relationship graph)",
        "                          |- WindowingSubsystem    (user-facing projection)",
        "Window lifetime    ->   WindowEnvelope",
        "                          |- WindowComponentStore  (PWI components)",
      ]),
      spacer(120),
      para([
        bold("Process lifetime"),
        normal(" is the outermost tier. "),
        mono("AppProcess"),
        normal(" is the only class at this level. It exists for the entire duration of the application, from the first meaningful object construction to the last cleanup before exit. Everything else in the layer lives within the boundary it establishes.")
      ]),
      spacer(80),
      para([
        bold("GUI lifetime"),
        normal(" is the middle tier. "),
        mono("GUIEngine"),
        normal(" and all the infrastructure it owns — "),
        mono("WindowDispatcher"),
        normal(", "),
        mono("WindowCoordinator"),
        normal(", "),
        mono("WindowHierarchy"),
        normal(", and "),
        mono("WindowingSubsystem"),
        normal(" — exist only while the GUI framework is active. None of these classes may be used before "),
        mono("GUIEngine"),
        normal(" is initialized, and none may outlive "),
        mono("GUIEngine\u2019s"),
        normal(" shutdown. The GUI tier is nested entirely within the process tier.")
      ]),
      spacer(80),
      para([
        bold("Window lifetime"),
        normal(" is the innermost tier. "),
        mono("WindowEnvelope"),
        normal(" and its owned "),
        mono("WindowComponentStore"),
        normal(" exist only while a specific window is alive within the running GUI. Windows may come and go during the GUI\u2019s lifetime, but no window envelope may exist before the GUI engine is active or outlive it. The window tier is nested entirely within the GUI tier.")
      ]),
      spacer(80),
      para([
        normal("This nesting is not a convention or a guideline — it is enforced structurally. "),
        mono("AppProcess"),
        normal(" owns "),
        mono("GUIEngine"),
        normal(". "),
        mono("GUIEngine"),
        normal(" owns "),
        mono("WindowCoordinator"),
        normal(", which owns every live "),
        mono("WindowEnvelope"),
        normal(". Destruction flows outward to inward: process tier tears down last, window tier tears down first. No object at any tier can outlive the tier above it because ownership prevents it.")
      ]),
      spacer(160),
      rule(),

      // ─── SECTION 3 ───────────────────────────────────────────────
      h1("3. The Classes at a Glance"),
      para([
        normal("The following table provides a concise orientation to each class in the process layer. Individual class description documents provide full detail on each entry.")
      ]),
      spacer(80),
      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [2000, 1400, 3360, 2600],
        rows: [
          new TableRow({
            tableHeader: true,
            children: [
              headerCell("Class"),
              headerCell("Lifetime Tier"),
              headerCell("Core Responsibility"),
              headerCell("Owns / Produces"),
            ]
          }),
          new TableRow({ children: [
            monoCell("AppProcess", false),
            dataCell("Process", false),
            dataCell("Owns the application lifecycle. Drives GUIEngine through a strictly sequenced initialization and shutdown. Enforces lifecycle invariants.", false),
            dataCell("Owns exactly one GUIEngine instance.", false),
          ]}),
          new TableRow({ children: [
            monoCell("GUIEngine", true),
            dataCell("GUI", true),
            dataCell("Owns and controls the GUI framework environment. Owns all GUI-scoped infrastructure. Enforces the invariant that no GUI-bound object exists outside of GUI lifetime.", true),
            dataCell("Owns WindowDispatcher, WindowCoordinator, WindowingSubsystem. Owns all WindowEnvelope instances indirectly.", true),
          ]}),
          new TableRow({ children: [
            monoCell("WindowDispatcher", false),
            dataCell("GUI", false),
            dataCell("The sole authority for window creation. Accepts WindowFactory registrations, validates dispatch constraints, executes factory callables, and hands off the result.", false),
            dataCell("Stores WindowFactory instances. Produces WindowEnvelope instances at dispatch time.", false),
          ]}),
          new TableRow({ children: [
            monoCell("WindowFactory", true),
            dataCell("GUI (stored)", true),
            dataCell("Bundles a factory callable with its descriptor flags. Gives the dispatcher everything it needs to decide whether and how to create a window.", true),
            dataCell("Carries a factory callable and a descriptor bitmask. Assigned a sequential factory ID by the dispatcher.", true),
          ]}),
          new TableRow({ children: [
            monoCell("WindowCoordinator", false),
            dataCell("GUI", false),
            dataCell("The lifetime authority for all live window envelopes. Receives, tracks, and eventually winds down every WindowEnvelope. Owns the window relationship graph.", false),
            dataCell("Owns all live WindowEnvelope instances. Owns WindowHierarchy.", false),
          ]}),
          new TableRow({ children: [
            monoCell("WindowHierarchy", true),
            dataCell("GUI (sub-component)", true),
            dataCell("Maintains the parent-child relationship graph between live window envelopes. Provides safe teardown traversal order.", true),
            dataCell("Owns the relationship graph data structure. Produces traversal order on request.", true),
          ]}),
          new TableRow({ children: [
            monoCell("WindowEnvelope", false),
            dataCell("Window", false),
            dataCell("The per-window infrastructure container. Bundles the raw backend window handle with Chevron-assigned identity and the window's component store.", false),
            dataCell("Holds the backend window handle. Owns WindowComponentStore.", false),
          ]}),
          new TableRow({ children: [
            monoCell("WindowInitContext", true),
            dataCell("Transient", true),
            dataCell("The dispatch-time initialization token. Authorizes and parameterizes the construction of a WindowEnvelope. Carries the parent handle for subsidiary window dispatches.", true),
            dataCell("Transient — exists for the duration of one factory call only. Carries no persistent state.", true),
          ]}),
          new TableRow({ children: [
            monoCell("WindowingSubsystem", false),
            dataCell("GUI", false),
            dataCell("The public-facing projection of GUIEngine\u2019s windowing capability. Orchestrates WindowDispatcher and WindowCoordinator on behalf of user code.", false),
            dataCell("Holds non-owning references to WindowDispatcher and WindowCoordinator. Does not own any infrastructure.", false),
          ]}),
        ]
      }),
      spacer(160),
      rule(),

      // ─── SECTION 4 ───────────────────────────────────────────────
      h1("4. The Lifecycle Walkthrough"),
      para([
        normal("The best way to understand how the process layer\u2019s classes work together is to follow a complete application lifecycle from the first line of user code to the final exit. What follows is that walkthrough — each class appearing at the moment it becomes relevant, its role in that moment described clearly.")
      ]),
      spacer(120),

      h2("Phase 1 — Process Setup"),
      para([
        normal("The user constructs an "),
        mono("AppProcess"),
        normal(" instance near the entry point. This is the first meaningful object in the system. It owns nothing yet — no engine, no windows — but it establishes the process-level authority that everything else will answer to. The application\u2019s lifecycle has begun.")
      ]),
      spacer(80),
      para([
        normal("The user then constructs a concrete "),
        mono("GUIEngine"),
        normal(" implementation — for example, "),
        mono("chevron::wx::Engine"),
        normal(". At this point the GUI framework has not been touched. No global state has been initialized. The engine exists as a configured object, ready to be committed. Configuration is still mutable here.")
      ]),
      spacer(80),
      para([
        normal("Before committing the engine, the user interacts with "),
        mono("WindowingSubsystem"),
        normal(" through "),
        mono("engine.windowing()"),
        normal(" to register their window factories. For each kind of window the application will have, the user constructs a "),
        mono("WindowFactory"),
        normal(" — pairing a factory callable with a descriptor bitmask — and submits it. "),
        mono("WindowDispatcher"),
        normal(" assigns each factory a sequential ID and stores it. The IDs are returned to the user, who may capture them as named constants for later use. This is the process-level declaration of window intent. No windows exist yet. No GUI work has occurred. These registrations are purely declarative.")
      ]),
      spacer(80),
      para([
        normal("The user commits the engine to "),
        mono("AppProcess"),
        normal(". Ownership transfers. Configuration is locked. The engine is now the chosen backend for the lifetime of the process. The process-level registration window closes — no new factories may be registered through this pathway until a post-commitment registration capability is designed.")
      ]),
      spacer(120),

      h2("Phase 2 \u2014 GUI Initialization"),
      para([
        normal("AppProcess"),
        normal(" instructs "),
        mono("GUIEngine"),
        normal(" to initialize. This is the moment the GUI framework comes alive. The framework\u2019s application object is created, environment assumptions are validated, and internal subsystems are prepared. "),
        mono("WindowDispatcher"),
        normal(", "),
        mono("WindowCoordinator"),
        normal(", "),
        mono("WindowHierarchy"),
        normal(", and "),
        mono("WindowingSubsystem"),
        normal(" are all already constructed as part of "),
        mono("GUIEngine"),
        normal(" \u2014 they have been ready since engine construction. The mainloop has not started. Windows do not exist yet.")
      ]),
      spacer(80),
      para([
        normal("If initialization fails at this point, no mainloop starts, no windows are created, and the application can exit cleanly. "),
        mono("AppProcess"),
        normal(" is informed and handles the error path. The system never reaches a half-alive state.")
      ]),
      spacer(120),

      h2("Phase 3 \u2014 Runtime Start"),
      para([
        normal("AppProcess"),
        normal(" calls "),
        mono("mainloopEntry()"),
        normal(", which honors the call by invoking "),
        mono("runtime()"),
        normal(" on the engine. This is the point of no return. The GUI engine becomes fully active.")
      ]),
      spacer(80),
      para([
        normal("The first action inside the running engine is the materialization of the startup window. "),
        mono("WindowDispatcher"),
        normal(" identifies the appropriate factory \u2014 either the one carrying the root window flag, or the first registered factory if no flag was set \u2014 and fires it. The factory callable receives a "),
        mono("WindowInitContext"),
        normal(" assembled by "),
        mono("GUIEngine"),
        normal(" at dispatch time. The context carries Chevron\u2019s internal bootstrapping data and, for subsidiary windows, the parent window handle. The factory constructs the backend window and passes it along with the context to Chevron\u2019s envelope construction function.")
      ]),
      spacer(80),
      para([
        normal("Chevron constructs a "),
        mono("WindowEnvelope"),
        normal(", assigns it an instance ID, and populates its "),
        mono("WindowComponentStore"),
        normal(" with the base per-window infrastructure (PWI) components unconditionally. The envelope is returned to "),
        mono("WindowDispatcher"),
        normal(", which immediately transfers ownership to "),
        mono("WindowCoordinator"),
        normal(". The coordinator registers the envelope in its registry, records its factory ID, and if applicable records its parent-child relationship in "),
        mono("WindowHierarchy"),
        normal(". The "),
        mono("WindowInitContext"),
        normal(" is consumed and destroyed. The window is now live.")
      ]),
      spacer(80),
      para([
        normal("The mainloop enters. "),
        mono("mainloopEntry()"),
        normal(" blocks. Control flow is inside the GUI framework. The application is running.")
      ]),
      spacer(120),

      h2("Phase 4 \u2014 Active Runtime"),
      para([
        normal("During normal operation, dispatch requests may arrive at any time from user interaction, application logic, or internal triggers. Each dispatch request flows through "),
        mono("WindowingSubsystem"),
        normal(" to "),
        mono("WindowDispatcher"),
        normal(". The dispatcher consults the relevant "),
        mono("WindowFactory\u2019s"),
        normal(" descriptor to verify constraints \u2014 single-instance checks query "),
        mono("WindowCoordinator"),
        normal(" by factory ID \u2014 and if all constraints are satisfied, fires the factory. The resulting envelope is transferred to "),
        mono("WindowCoordinator"),
        normal(" and the coordinator updates its registry and "),
        mono("WindowHierarchy"),
        normal(" accordingly.")
      ]),
      spacer(80),
      para([
        normal("WindowCoordinator"),
        normal(" watches the full population of live envelopes at all times. When a window closes, its envelope leaves the registry. If the last envelope leaves, the coordinator surfaces a last-window-closed event to "),
        mono("GUIEngine"),
        normal(", which may in turn signal "),
        mono("AppProcess"),
        normal(" to begin shutdown. The coordinator does not initiate shutdown itself \u2014 it observes, records, and notifies. The decision of what to do belongs to "),
        mono("GUIEngine"),
        normal(" and ultimately to "),
        mono("AppProcess"),
        normal(".")
      ]),
      spacer(120),

      h2("Phase 5 \u2014 Shutdown and Teardown"),
      para([
        normal("Shutdown may be initiated from three sources: user code calling shutdown explicitly, the GUI framework initiating exit when the root window closes, or "),
        mono("AppProcess"),
        normal(" requesting it programmatically. All three paths converge on "),
        mono("GUIEngine"),
        normal(", which coordinates the teardown sequence. Calling shutdown twice is always safe.")
      ]),
      spacer(80),
      para([
        normal("The mainloop stops. "),
        mono("WindowCoordinator"),
        normal(" asks "),
        mono("WindowHierarchy"),
        normal(" for a safe teardown traversal order \u2014 children before parents, windows with no registered parent addressed last. Each envelope is wound down in that order: its "),
        mono("WindowComponentStore"),
        normal(" components are destroyed in reverse registration order, the backend window handle is released last, and the envelope is removed from the coordinator\u2019s registry and from "),
        mono("WindowHierarchy"),
        normal(".")
      ]),
      spacer(80),
      para([
        normal("Once all envelopes are gone, "),
        mono("WindowingSubsystem"),
        normal(" is destroyed \u2014 before the components it references, since it holds non-owning references to "),
        mono("WindowDispatcher"),
        normal(" and "),
        mono("WindowCoordinator"),
        normal(" and must not outlive either. The GUI framework is then deinitialized. Control returns to "),
        mono("AppProcess"),
        normal(", which completes its own cleanup and returns an exit code to the process.")
      ]),
      spacer(160),
      rule(),

      // ─── SECTION 5 ───────────────────────────────────────────────
      h1("5. Ownership and Authority"),
      para([
        normal("Understanding who owns what and who is authoritative over what is essential for reasoning about correctness in the process layer. These are not informal conventions \u2014 they are structural properties enforced through the design.")
      ]),
      spacer(120),

      h2("The Ownership Chain"),
      para("Ownership in the process layer is hierarchical and unambiguous:"),
      spacer(80),
      bullet([mono("AppProcess"), normal(" owns exactly one "), mono("GUIEngine"), normal(" instance for the lifetime of the process.")]),
      bullet([mono("GUIEngine"), normal(" owns "), mono("WindowDispatcher"), normal(", "), mono("WindowCoordinator"), normal(", and "), mono("WindowingSubsystem"), normal(" at the base class level. These are written once and shared across all concrete backend implementations.")]),
      bullet([mono("WindowCoordinator"), normal(" owns all live "), mono("WindowEnvelope"), normal(" instances and owns "), mono("WindowHierarchy"), normal(".")]),
      bullet([mono("WindowEnvelope"), normal(" owns the raw backend window handle and its "), mono("WindowComponentStore"), normal(".")]),
      bullet([mono("WindowingSubsystem"), normal(" holds non-owning references to "), mono("WindowDispatcher"), normal(" and "), mono("WindowCoordinator"), normal(". It does not own them. It is destroyed before they are.")]),
      bullet([mono("WindowFactory"), normal(" instances are stored inside "), mono("WindowDispatcher"), normal(". The dispatcher owns them.")]),
      bullet([mono("WindowInitContext"), normal(" is transient — assembled by "), mono("GUIEngine"), normal(" at dispatch time, consumed during factory execution, and gone.")]),
      spacer(120),

      h2("The Authority Split"),
      para([
        normal("Authority in the process layer is separated from ownership in meaningful ways. The most important split is between creation authority and lifetime authority in the windowing system.")
      ]),
      spacer(80),
      para([
        bold("WindowDispatcher"),
        normal(" is the "),
        bold("creation authority"),
        normal(". It decides whether a window is allowed to exist right now and, if so, executes the factory that produces it. Once a window has been created and handed off, the dispatcher has no further authority over it. It is done.")
      ]),
      spacer(80),
      para([
        bold("WindowCoordinator"),
        normal(" is the "),
        bold("lifetime authority"),
        normal(". It owns every live envelope from the moment the dispatcher hands one over. It tracks identities, manages relationships through "),
        mono("WindowHierarchy"),
        normal(", detects lifecycle events, and governs teardown. It knows everything about what windows currently exist. The dispatcher knows nothing about this.")
      ]),
      spacer(80),
      para([
        normal("This split is deliberate and non-negotiable. Combining creation and lifetime authority into a single class would produce an unmanageable god object. Separating them gives each class a clean, focused responsibility and makes both independently testable and understandable.")
      ]),
      spacer(120),

      h2("The Dependency Direction"),
      para([
        normal("Dependencies in the process layer flow in one direction: inward. "),
        mono("AppProcess"),
        normal(" depends on "),
        mono("GUIEngine"),
        normal(" through a polymorphic interface. "),
        mono("GUIEngine"),
        normal(" depends on its owned components. "),
        mono("WindowDispatcher"),
        normal(" depends on "),
        mono("WindowCoordinator"),
        normal(" through a narrow query interface for single-instance checks — but "),
        mono("WindowCoordinator"),
        normal(" does not depend on "),
        mono("WindowDispatcher"),
        normal(". This one-way dependency is intentional. The coordinator is a full participant in the window lifecycle. The dispatcher is a mechanism that fires and steps aside.")
      ]),
      spacer(80),
      para([
        mono("WindowingSubsystem"),
        normal(" depends on both "),
        mono("WindowDispatcher"),
        normal(" and "),
        mono("WindowCoordinator"),
        normal(" through non-owning references. Neither of those components depends on "),
        mono("WindowingSubsystem"),
        normal(". The subsystem is a projection over them, not a participant in their internal operations.")
      ]),
      spacer(160),
      rule(),

      // ─── SECTION 6 ───────────────────────────────────────────────
      h1("6. The Windowing Subsystem \u2014 A Closer Look"),
      para([
        normal("Of the nine classes in the process layer, "),
        mono("WindowingSubsystem"),
        normal(" has the most unusual character: it owns nothing, it enforces nothing independently, and it has no lifecycle of its own beyond its references. Yet it is the most important class from user code\u2019s perspective, because it is the only windowing surface user code ever sees.")
      ]),
      spacer(80),
      para([
        normal("Understanding "),
        mono("WindowingSubsystem"),
        normal(" requires understanding the problem it solves. As "),
        mono("GUIEngine\u2019s"),
        normal(" windowing capabilities grow, every user-facing windowing operation \u2014 factory registration, window dispatch, live window queries, component access, subsidiary window parenting \u2014 would naturally accumulate on "),
        mono("GUIEngine\u2019s"),
        normal(" own API. None of these operations belong to "),
        mono("GUIEngine\u2019s"),
        normal(" actual identity, which is lifecycle governance. Letting them accumulate there produces a class that is simultaneously a lifecycle authority and an operational windowing API \u2014 two responsibilities that have no business sharing a surface.")
      ]),
      spacer(80),
      para([
        mono("WindowingSubsystem"),
        normal(" solves this by being the coherent home for those operations. "),
        mono("GUIEngine\u2019s"),
        normal(" API stays focused on initialization, mainloop control, and shutdown. Everything a user needs to do with windows flows through "),
        mono("engine.windowing()"),
        normal(" instead. The subsystem holds non-owning references to "),
        mono("WindowDispatcher"),
        normal(" and "),
        mono("WindowCoordinator"),
        normal(" and orchestrates their collaboration on behalf of user code.")
      ]),
      spacer(80),
      para([
        normal("The key property that makes this work without creating confusion is that "),
        mono("WindowDispatcher"),
        normal(" and "),
        mono("WindowCoordinator"),
        normal(" retain their full independence. They continue to collaborate directly for internal purposes \u2014 the single-instance query, the envelope handoff, last-window-close notification \u2014 without "),
        mono("WindowingSubsystem"),
        normal(" being involved. The subsystem handles only operations that originate from user code. Internal operations bypass it entirely.")
      ]),
      spacer(80),
      para([
        normal("This is the first instance of an explicit, repeatable pattern in Chevron: the "),
        bold("subsystem projection pattern"),
        normal(". Whenever a cluster of internal components together form a coherent user-facing capability, a dedicated projection class surfaces that capability without those components surrendering their independence. "),
        mono("WindowingSubsystem"),
        normal(" is the template. As the library grows, additional subsystems \u2014 event routing, memory management, threading \u2014 will follow the same pattern.")
      ]),
      spacer(160),
      rule(),

      // ─── SECTION 7 ───────────────────────────────────────────────
      h1("7. Layer Boundaries \u2014 Scope and Responsibility"),
      para([
        normal("A layer\u2019s boundaries are defined by its purpose, not by an arbitrary list of exclusions. Understanding where the process layer ends requires understanding what it is fundamentally trying to do \u2014 and then recognizing that everything outside that purpose belongs somewhere else.")
      ]),
      spacer(120),

      h2("The Boundary Defined"),
      para([
        normal("The process layer\u2019s purpose is precisely this: "),
        bold("to own the structural mechanics that make a GUI application well-formed"),
        normal(". Well-formed means the application starts correctly, runs without violating its own invariants, and exits cleanly regardless of how shutdown is triggered. The layer concerns itself with the question of "),
        italic("how"),
        normal(" the application is structured and governed, not "),
        italic("what"),
        normal(" the application does.")
      ]),
      spacer(80),
      para([
        normal("From this purpose, the boundary draws itself. A concern belongs in the process layer if and only if it is a universal structural mechanic that every well-formed GUI application under Chevron must have, regardless of its domain, regardless of which GUI framework it uses, and regardless of what it is trying to accomplish for its users. It must be the kind of thing that, if left to user code, would be either consistently gotten wrong or consistently reimplemented with slight variations that introduce subtle differences in correctness.")
      ]),
      spacer(80),
      para([
        normal("Everything that passes that test is in the layer. Everything that fails it is not."),
      ]),
      spacer(120),

      h2("Where the Boundary Sits"),
      para([
        normal("Applying that definition makes the boundary precise:")
      ]),
      spacer(80),
      para([
        bold("Inside the boundary \u2014 structural application mechanics:"),
      ]),
      bullet([normal("Application lifetime ownership and sequencing \u2014 this is universal to every application and must be correct")]),
      bullet([normal("GUI framework environment governance \u2014 frameworks are environments with global state and threading requirements that must be tamed")]),
      bullet([normal("Window creation authority and dispatch policy \u2014 ad-hoc window creation scatters responsibility and produces inconsistent behavior")]),
      bullet([normal("Live window tracking and lifetime management \u2014 something must own windows and know when they are gone")]),
      bullet([normal("Window relationship tracking \u2014 parent-child relationships affect teardown ordering and must be recorded")]),
      bullet([normal("Per-window infrastructure provisioning \u2014 the structural scaffolding every window needs (identity, memory, logging context, view machinery)"])),
      bullet([normal("Lifecycle sequencing and invariant enforcement \u2014 the guarantees that prevent the system from ever reaching a half-alive state")]),
      spacer(80),
      para([
        bold("Outside the boundary \u2014 application domain and framework surface:"),
      ]),
      bullet([normal("Widgets, layout, and visual composition \u2014 these are the framework\u2019s domain and vary by framework. Chevron has no opinion on them and deliberately provides no abstraction over them.")]),
      bullet([normal("Event handling and routing beyond lifecycle signals \u2014 user interaction events are application logic, not structural mechanics. Chevron\u2019s future EventSubsystem will provide infrastructure here, but it is a separate concern.")]),
      bullet([normal("Business logic and domain models \u2014 what the application does for its users is entirely outside Chevron\u2019s scope")]),
      bullet([normal("Cross-GUI-framework portability at the user-code level \u2014 Chevron does not provide a unified GUI API. User code is written against the chosen framework directly.")]),
      bullet([normal("Non-GUI services \u2014 networking, file I/O, database access, and similar concerns are not GUI application infrastructure")]),
      spacer(120),

      h2("Why the Boundary Must Be Held"),
      para([
        normal("The process layer\u2019s value comes precisely from its focus. A layer that owns everything owns nothing well. By confining itself to structural application mechanics, the process layer can make strong correctness guarantees about everything within its boundary. The moment it takes on concerns outside that boundary \u2014 trying to abstract widgets, providing convenience wrappers for events, or touching domain logic \u2014 those guarantees erode because the scope has grown beyond what can be reasoned about cleanly.")
      ]),
      spacer(80),
      para([
        normal("Chevron\u2019s philosophy is that it is application infrastructure, not a GUI framework abstraction. The process layer is the clearest expression of that philosophy in concrete form. Every class in it exists because a well-formed GUI application cannot be built without what that class provides. None of them exist because they make GUI programming more convenient in a general sense. That distinction \u2014 "),
        italic("necessary structural mechanics"),
        normal(" versus "),
        italic("convenient framework wrappers"),
        normal(" \u2014 is the boundary, stated in its most essential form.")
      ]),
      spacer(160),
      rule(),

      // Footer
      new Paragraph({
        children: [new TextRun({ text: "Chevron Library \u2014 Internal Design Documentation", font: FONT, size: 18, color: "AAAAAA", italics: true })],
        alignment: AlignmentType.CENTER,
        spacing: { before: 160 }
      })
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/mnt/user-data/outputs/AppProcessLayer_Outline.docx', buffer);
  console.log('Done');
});
