const {
  Document, Packer, Paragraph, TextRun, HeadingLevel,
  AlignmentType, LevelFormat, BorderStyle, WidthType,
  ShadingType, VerticalAlign
} = require('docx');
const fs = require('fs');

const FONT   = "Arial";
const MONO   = "Courier New";
const BLUE   = "2E5FA3";
const DARK   = "1A1A1A";
const MID    = "555555";
const RULE   = "CCCCCC";

// ── primitives ──────────────────────────────────────────────────────────────

function rule() {
  return new Paragraph({
    children: [],
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: RULE, space: 1 } },
    spacing: { before: 80, after: 160 }
  });
}

function spacer(pts = 120) {
  return new Paragraph({ children: [], spacing: { before: 0, after: pts } });
}

function normal(text) {
  return new TextRun({ text, font: FONT, size: 22, color: DARK });
}

function bold(text) {
  return new TextRun({ text, font: FONT, size: 22, bold: true, color: DARK });
}

function italic(text) {
  return new TextRun({ text, font: FONT, size: 22, italics: true, color: MID });
}

function mono(text) {
  return new TextRun({ text, font: MONO, size: 20, color: DARK });
}

function para(runs, before = 80, after = 120) {
  const children = typeof runs === 'string'
    ? [new TextRun({ text: runs, font: FONT, size: 22, color: DARK })]
    : runs;
  return new Paragraph({ children, spacing: { before, after } });
}

function h1(text) {
  return new Paragraph({
    pStyle: "Heading1",
    children: [new TextRun({ text, font: FONT, size: 36, bold: true, color: BLUE })]
  });
}

function h2(text) {
  return new Paragraph({
    pStyle: "Heading2",
    children: [new TextRun({ text, font: FONT, size: 26, bold: true, color: DARK })]
  });
}

function bullet(runs, ref = "bullets") {
  const children = typeof runs === 'string'
    ? [new TextRun({ text: runs, font: FONT, size: 22, color: DARK })]
    : runs;
  return new Paragraph({ numbering: { reference: ref, level: 0 }, children, spacing: { before: 60, after: 60 } });
}

function blockquote(text) {
  return new Paragraph({
    children: [new TextRun({ text, font: FONT, size: 22, italics: true, color: MID })],
    indent: { left: 720 },
    border: { left: { style: BorderStyle.SINGLE, size: 12, color: BLUE, space: 10 } },
    spacing: { before: 120, after: 120 }
  });
}

function codeLines(lines) {
  return lines.map((line, i) => new Paragraph({
    children: [new TextRun({ text: line, font: MONO, size: 20, color: BLUE })],
    shading: { val: ShadingType.CLEAR, fill: "F4F4F4" },
    spacing: { before: i === 0 ? 100 : 0, after: i === lines.length - 1 ? 100 : 0 },
    indent: { left: 720 }
  }));
}

