#pragma once

#include <cstddef>
#include <cstdint>
#include <atomic>
#include <cassert>
#include <sys/mman.h>   // mmap / munmap — OS slab acquisition on POSIX
                        // (platform-specific, would be conditionally compiled
                        //  for Windows/macOS in the real implementation)

namespace chevron::memory {


// ---------------------------------------------------------------------------
// MemoryRegion
//
// Lightweight value type representing a contiguous region of memory.
// No ownership semantics — the caller is responsible for the region
// until it posts a return event to the event loop.
// ---------------------------------------------------------------------------
struct MemoryRegion {
    void*       base = nullptr;
    std::size_t size = 0;

    [[nodiscard]] bool valid() const noexcept { return base != nullptr && size > 0; }
};


// ---------------------------------------------------------------------------
// SlabDescriptor
//
// Metadata for a single OS-acquired slab. Kept in a separate contiguous
// array rather than embedded at the head of each slab, so the slab memory
// itself is clean and fully available to consumers.
//
// A slab is a large raw allocation from the OS (e.g. 64 MB). Blocks are
// carved out of slabs sequentially via a bump offset.
// ---------------------------------------------------------------------------
struct SlabDescriptor {
    void*                    base        = nullptr;  // base address of this slab
    std::size_t              capacity    = 0;         // total slab size in bytes
    std::atomic<std::size_t> bump_offset { 0 };      // next unused byte offset within slab

    // Slabs are not copyable — each descriptor is unique and owns its OS allocation.
    SlabDescriptor() = default;
    SlabDescriptor(const SlabDescriptor&) = delete;
    SlabDescriptor& operator=(const SlabDescriptor&) = delete;

    // Move is allowed so the descriptor array can be constructed in-place.
    SlabDescriptor(SlabDescriptor&& other) noexcept
        : base(other.base)
        , capacity(other.capacity)
        , bump_offset(other.bump_offset.load(std::memory_order_relaxed))
    {
        other.base     = nullptr;
        other.capacity = 0;
    }
};


// ---------------------------------------------------------------------------
// ProcessMemoryPool
//
// The internal memory substrate owned by MemoryCore. Responsible for:
//
//   1. Acquiring large fixed-size slabs from the OS via mmap.
//   2. Sub-allocating fixed-size blocks from those slabs via atomic bump.
//   3. Maintaining a lock-free free list of returned blocks for re-issue.
//   4. Enforcing a hard budget ceiling on total OS-committed bytes.
//
// Thread safety:
//   - acquire() is fully thread-safe via atomic bump pointer.
//   - release() is called exclusively from the event loop thread,
//     making the free list a single-writer structure (no CAS needed on push).
//   - claim_from_free_list() is multi-reader but single-writer, so a
//     simple atomic index is sufficient.
//
// This class is a value member of MemoryCore — no heap allocation,
// no pointer indirection.
// ---------------------------------------------------------------------------
class ProcessMemoryPool {

public:

    // Maximum number of slabs this pool will ever manage.
    // A handful of 64 MB slabs covers the vast majority of GUI applications.
    static constexpr std::size_t MAX_SLABS = 16;

    // Maximum number of blocks sitting in the free list at any one time.
    // Sized generously to avoid blocking the event loop return path.
    static constexpr std::size_t FREE_LIST_CAPACITY = 256;


    // -----------------------------------------------------------------------
    // Construction / destruction
    // -----------------------------------------------------------------------

    // block_size_bytes : size of each block handed to MemoryScope instances.
    //                    Must be a multiple of the OS page size (typically 4 KB).
    //                    A value of 64 MB is the expected production default.
    //
    // budget_ceiling   : maximum total bytes the pool may acquire from the OS
    //                    across all slabs combined. Hard limit — never exceeded.
    explicit ProcessMemoryPool(std::size_t block_size_bytes,
                               std::size_t budget_ceiling) noexcept
        : block_size_(block_size_bytes)
        , budget_ceiling_(budget_ceiling)
        , committed_bytes_(0)
        , slab_count_(0)
        , free_list_head_(0)
        , free_list_tail_(0)
    {
        assert(block_size_bytes > 0);
        assert(budget_ceiling   > 0);
        assert(block_size_bytes <= budget_ceiling);
    }

    ~ProcessMemoryPool() noexcept {
        // Return all slabs to the OS.
        for (std::size_t i = 0; i < slab_count_; ++i) {
            if (slabs_[i].base) {
                ::munmap(slabs_[i].base, slabs_[i].capacity);
            }
        }
    }

    // Not copyable or movable — this is a value member of MemoryCore and
    // must not be relocated after construction.
    ProcessMemoryPool(const ProcessMemoryPool&)            = delete;
    ProcessMemoryPool& operator=(const ProcessMemoryPool&) = delete;
    ProcessMemoryPool(ProcessMemoryPool&&)                 = delete;
    ProcessMemoryPool& operator=(ProcessMemoryPool&&)      = delete;


    // -----------------------------------------------------------------------
    // preallocate()
    //
    // Eagerly acquires `block_count` blocks from the OS upfront.
    // Called once by MemoryCore before any MemoryScope attaches.
    // Pays the OS allocation cost at startup, amortising it across the
    // entire application lifetime — the "drip not landslide" principle.
    //
    // Returns false if the budget ceiling would be exceeded.
    // -----------------------------------------------------------------------
    [[nodiscard]] bool preallocate(std::size_t block_count) noexcept {
        for (std::size_t i = 0; i < block_count; ++i) {
            if (!acquire_slab()) {
                return false;   // budget ceiling reached
            }
        }
        return true;
    }


    // -----------------------------------------------------------------------
    // acquire()
    //
    // Hand a block to a requesting MemoryScope.
    //
    // Strategy (in priority order):
    //   1. Check the free list for a previously returned block — free and
    //      local, no OS involvement, cheapest possible path.
    //   2. Bump into the current slab if space remains.
    //   3. Acquire a new slab from the OS if under budget.
    //   4. Return an invalid MemoryRegion if the budget ceiling is reached.
    //
    // Thread-safe: the slab bump pointer is atomic. Multiple MemoryScope
    // instances on different threads may call acquire() concurrently.
    // -----------------------------------------------------------------------
    [[nodiscard]] MemoryRegion acquire() noexcept {

        // Step 1: free list check first — avoid touching the OS or even the
        // slab bump pointer if a returned block is already sitting here.
        {
            MemoryRegion recycled = claim_from_free_list();
            if (recycled.valid()) {
                return recycled;
            }
        }

        // Step 2 & 3: try to bump within an existing slab, or acquire a new one.
        return bump_block();
    }


    // -----------------------------------------------------------------------
    // release()
    //
    // Called EXCLUSIVELY from the event loop thread when processing a memory
    // return event posted by a MemoryScope.
    //
    // Because only one thread ever calls release(), the free list push is a
    // simple array write with an atomic tail increment — no CAS needed.
    // This is the single-writer property the event loop design gives us.
    // -----------------------------------------------------------------------
    void release(MemoryRegion region) noexcept {
        assert(region.valid());
        assert(region.size == block_size_);   // only whole blocks are returned

        std::size_t tail = free_list_tail_.load(std::memory_order_relaxed);

        if (tail - free_list_head_.load(std::memory_order_acquire) >= FREE_LIST_CAPACITY) {
            // Free list is full — this should be extremely rare given the
            // capacity. In production this would log a warning. For now, the
            // block is simply dropped back to the committed pool (not returned
            // to the OS — the slab it belongs to still owns that memory).
            return;
        }

        free_list_[tail % FREE_LIST_CAPACITY] = region;
        free_list_tail_.store(tail + 1, std::memory_order_release);
    }


    // -----------------------------------------------------------------------
    // Diagnostics
    // -----------------------------------------------------------------------

    struct Stats {
        std::size_t block_size;         // size of each block in bytes
        std::size_t budget_ceiling;     // max bytes allowed from OS
        std::size_t committed_bytes;    // bytes currently held from OS
        std::size_t slab_count;         // number of slabs acquired so far
        std::size_t free_list_depth;    // blocks currently sitting in free list
    };

    [[nodiscard]] Stats stats() const noexcept {
        return Stats {
            .block_size      = block_size_,
            .budget_ceiling  = budget_ceiling_,
            .committed_bytes = committed_bytes_.load(std::memory_order_relaxed),
            .slab_count      = slab_count_,
            .free_list_depth = free_list_tail_.load(std::memory_order_relaxed)
                             - free_list_head_.load(std::memory_order_relaxed)
        };
    }


private:

    // -----------------------------------------------------------------------
    // acquire_slab()
    //
    // Asks the OS for one new slab of `block_size_` bytes via mmap.
    // Updates committed_bytes_ and registers the slab descriptor.
    //
    // Called from preallocate() at startup and from bump_block() on demand
    // when an existing slab is exhausted and budget permits.
    // -----------------------------------------------------------------------
    [[nodiscard]] bool acquire_slab() noexcept {
        if (slab_count_ >= MAX_SLABS) {
            return false;   // descriptor array is full
        }

        std::size_t current = committed_bytes_.load(std::memory_order_relaxed);
        if (current + block_size_ > budget_ceiling_) {
            return false;   // budget ceiling would be exceeded
        }

        // MAP_ANONYMOUS | MAP_PRIVATE: no file backing, private to this process.
        // PROT_READ | PROT_WRITE: readable and writable.
        void* ptr = ::mmap(nullptr,
                           block_size_,
                           PROT_READ | PROT_WRITE,
                           MAP_ANONYMOUS | MAP_PRIVATE,
                           -1, 0);

        if (ptr == MAP_FAILED) {
            return false;   // OS refused the allocation (OOM or limit hit)
        }

        // Register the descriptor. slab_count_ is only written from one
        // location (here) which is only reached from preallocate() (single
        // caller before any scope attaches) or from bump_block() which is
        // protected by a compare-exchange on committed_bytes_.
        SlabDescriptor& desc = slabs_[slab_count_];
        desc.base     = ptr;
        desc.capacity = block_size_;
        desc.bump_offset.store(0, std::memory_order_relaxed);

        // Publish the committed byte count. This is the budget enforcement
        // point — visible to all threads immediately.
        committed_bytes_.fetch_add(block_size_, std::memory_order_release);
        ++slab_count_;  // slab_count_ itself is not atomic; see note below.
                        // NOTE: slab_count_ is only written here, and acquire_slab()
                        // is called either during single-threaded preallocate() or
                        // while holding the implicit serialisation of the CAS in
                        // bump_block(). In a full implementation this would be
                        // made atomic or protected by a mutex for safety.

        return true;
    }


    // -----------------------------------------------------------------------
    // bump_block()
    //
    // Attempts to carve one block out of the most recently acquired slab
    // using an atomic fetch_add on the slab's bump offset.
    //
    // If the current slab is full, tries to acquire a new one from the OS.
    //
    // This is the path taken when the free list is empty.
    // -----------------------------------------------------------------------
    [[nodiscard]] MemoryRegion bump_block() noexcept {
        // Try each slab from newest to oldest. In practice nearly all
        // successful bumps will hit the last slab (index slab_count_-1).
        for (std::size_t i = slab_count_; i-- > 0; ) {
            SlabDescriptor& slab = slabs_[i];

            // Atomically reserve `block_size_` bytes within this slab.
            std::size_t offset = slab.bump_offset.fetch_add(
                block_size_, std::memory_order_relaxed);

            if (offset + block_size_ <= slab.capacity) {
                // Success — the reservation is within bounds.
                return MemoryRegion {
                    .base = static_cast<char*>(slab.base) + offset,
                    .size = block_size_
                };
            }

            // This slab is exhausted. The fetch_add overshot — that's fine;
            // the wasted bytes at the end of the slab are simply unused.
            // Continue to the next slab (or acquire a new one).
        }

        // All existing slabs are full. Try to acquire a new one from the OS.
        if (acquire_slab()) {
            return bump_block();    // recurse once into the freshly acquired slab
        }

        // Budget ceiling reached — caller must handle this.
        return MemoryRegion{};
    }


    // -----------------------------------------------------------------------
    // claim_from_free_list()
    //
    // Attempts to pop one block from the free list.
    //
    // The free list is single-writer (event loop) / multi-reader (any thread
    // calling acquire()). Readers use a CAS on the head index to claim slots
    // without conflicting with each other.
    // -----------------------------------------------------------------------
    [[nodiscard]] MemoryRegion claim_from_free_list() noexcept {
        std::size_t head = free_list_head_.load(std::memory_order_acquire);

        while (true) {
            std::size_t tail = free_list_tail_.load(std::memory_order_acquire);

            if (head == tail) {
                return MemoryRegion{};   // free list is empty
            }

            // Try to claim this slot by advancing the head index.
            if (free_list_head_.compare_exchange_weak(
                    head, head + 1,
                    std::memory_order_acq_rel,
                    std::memory_order_acquire))
            {
                return free_list_[head % FREE_LIST_CAPACITY];
            }

            // Another thread beat us to it — retry with the updated head.
        }
    }


    // -----------------------------------------------------------------------
    // Member variables
    // -----------------------------------------------------------------------

    // Configuration — immutable after construction.
    std::size_t block_size_;        // size of each block handed to scopes
    std::size_t budget_ceiling_;    // hard OS allocation ceiling in bytes

    // OS budget tracking — atomic so all threads see the same committed total.
    std::atomic<std::size_t> committed_bytes_;

    // Slab descriptor array — contiguous metadata, separate from slab memory.
    // Fits in a few cache lines for the typical handful-of-slabs case.
    SlabDescriptor slabs_[MAX_SLABS];
    std::size_t    slab_count_;     // number of slabs currently in use

    // Free list — ring buffer of returned block pointers.
    // Single writer (event loop thread via release()), multi-reader (acquire()).
    MemoryRegion                free_list_[FREE_LIST_CAPACITY];
    std::atomic<std::size_t>    free_list_head_;    // next slot to claim (readers)
    std::atomic<std::size_t>    free_list_tail_;    // next slot to write (writer)

};


} // namespace chevron::memory

