        free_list_[tail % FREE_LIST_CAPACITY] = region;
        free_list_tail_.store(tail + 1, std::memory_order_release);
    }


    // -----------------------------------------------------------------------
    // Diagnostics
    // -----------------------------------------------------------------------

    struct Stats {
        std::size_t block_size;         // size of each block in bytes
        std::size_t budget_ceiling;     // max bytes allowed from OS
        std::size_t committed_bytes;    // bytes currently held from OS
        std::size_t slab_count;         // number of slabs acquired so far
        std::size_t free_list_depth;    // blocks currently sitting in free list
    };

    [[nodiscard]] Stats stats() const noexcept {
        return Stats {
            .block_size      = block_size_,
            .budget_ceiling  = budget_ceiling_,
            .committed_bytes = committed_bytes_.load(std::memory_order_relaxed),
            .slab_count      = slab_count_,
            .free_list_depth = free_list_tail_.load(std::memory_order_relaxed)
                             - free_list_head_.load(std::memory_order_relaxed)
        };
    }


private:

    // -----------------------------------------------------------------------
    // acquire_slab()
    //
    // Asks the OS for one new slab of `block_size_` bytes via mmap.
    // Updates committed_bytes_ and registers the slab descriptor.
    //
    // Called from preallocate() at startup and from bump_block() on demand
    // when an existing slab is exhausted and budget permits.
    // -----------------------------------------------------------------------
    [[nodiscard]] bool acquire_slab() noexcept {
        if (slab_count_ >= MAX_SLABS) {
            return false;   // descriptor array is full
        }

        std::size_t current = committed_bytes_.load(std::memory_order_relaxed);
        if (current + block_size_ > budget_ceiling_) {
            return false;   // budget ceiling would be exceeded
        }

        // MAP_ANONYMOUS | MAP_PRIVATE: no file backing, private to this process.
        // PROT_READ | PROT_WRITE: readable and writable.
        void* ptr = ::mmap(nullptr,
                           block_size_,
                           PROT_READ | PROT_WRITE,
                           MAP_ANONYMOUS | MAP_PRIVATE,
                           -1, 0);

        if (ptr == MAP_FAILED) {
            return false;   // OS refused the allocation (OOM or limit hit)
        }

        // Register the descriptor. slab_count_ is only written from one
        // location (here) which is only reached from preallocate() (single
        // caller before any scope attaches) or from bump_block() which is
        // protected by a compare-exchange on committed_bytes_.
        SlabDescriptor& desc = slabs_[slab_count_];
        desc.base     = ptr;
        desc.capacity = block_size_;
        desc.bump_offset.store(0, std::memory_order_relaxed);

        // Publish the committed byte count. This is the budget enforcement
        // point — visible to all threads immediately.
        committed_bytes_.fetch_add(block_size_, std::memory_order_release);
        ++slab_count_;  // slab_count_ itself is not atomic; see note below.
                        // NOTE: slab_count_ is only written here, and acquire_slab()
                        // is called either during single-threaded preallocate() or
                        // while holding the implicit serialisation of the CAS in
                        // bump_block(). In a full implementation this would be
                        // made atomic or protected by a mutex for safety.

        return true;
    }


    // -----------------------------------------------------------------------
    // bump_block()
    //
    // Attempts to carve one block out of the most recently acquired slab
    // using an atomic fetch_add on the slab's bump offset.
    //
    // If the current slab is full, tries to acquire a new one from the OS.
    //
    // This is the path taken when the free list is empty.
    // -----------------------------------------------------------------------
    [[nodiscard]] MemoryRegion bump_block() noexcept {
        // Try each slab from newest to oldest. In practice nearly all
        // successful bumps will hit the last slab (index slab_count_-1).
        for (std::size_t i = slab_count_; i-- > 0; ) {
            SlabDescriptor& slab = slabs_[i];

            // Atomically reserve `block_size_` bytes within this slab.
            std::size_t offset = slab.bump_offset.fetch_add(
                block_size_, std::memory_order_relaxed);

            if (offset + block_size_ <= slab.capacity) {
                // Success — the reservation is within bounds.
                return MemoryRegion {
                    .base = static_cast<char*>(slab.base) + offset,
                    .size = block_size_
                };
            }

            // This slab is exhausted. The fetch_add overshot — that's fine;
            // the wasted bytes at the end of the slab are simply unused.
            // Continue to the next slab (or acquire a new one).
        }

        // All existing slabs are full. Try to acquire a new one from the OS.
        if (acquire_slab()) {
            return bump_block();    // recurse once into the freshly acquired slab
        }

        // Budget ceiling reached — caller must handle this.
        return MemoryRegion{};
    }


    // -----------------------------------------------------------------------
    // claim_from_free_list()
    //
    // Attempts to pop one block from the free list.
    //
    // The free list is single-writer (event loop) / multi-reader (any thread
    // calling acquire()). Readers use a CAS on the head index to claim slots
    // without conflicting with each other.
    // -----------------------------------------------------------------------
    [[nodiscard]] MemoryRegion claim_from_free_list() noexcept {
        std::size_t head = free_list_head_.load(std::memory_order_acquire);

        while (true) {
            std::size_t tail = free_list_tail_.load(std::memory_order_acquire);

            if (head == tail) {
                return MemoryRegion{};   // free list is empty
            }

            // Try to claim this slot by advancing the head index.
            if (free_list_head_.compare_exchange_weak(
                    head, head + 1,
                    std::memory_order_acq_rel,
                    std::memory_order_acquire))
            {
                return free_list_[head % FREE_LIST_CAPACITY];
            }

            // Another thread beat us to it — retry with the updated head.
        }
    }


    // -----------------------------------------------------------------------
    // Member variables
    // -----------------------------------------------------------------------

    // Configuration — immutable after construction.
    std::size_t block_size_;        // size of each block handed to scopes
    std::size_t budget_ceiling_;    // hard OS allocation ceiling in bytes

    // OS budget tracking — atomic so all threads see the same committed total.
    std::atomic<std::size_t> committed_bytes_;

    // Slab descriptor array — contiguous metadata, separate from slab memory.
    // Fits in a few cache lines for the typical handful-of-slabs case.
    SlabDescriptor slabs_[MAX_SLABS];
    std::size_t    slab_count_;     // number of slabs currently in use

    // Free list — ring buffer of returned block pointers.
    // Single writer (event loop thread via release()), multi-reader (acquire()).
    MemoryRegion                free_list_[FREE_LIST_CAPACITY];
    std::atomic<std::size_t>    free_list_head_;    // next slot to claim (readers)
    std::atomic<std::size_t>    free_list_tail_;    // next slot to write (writer)

};


