```cpp
// ===================================================================================== //
// PART 1: How a user establishes a component type
//
// Every component type — whether Chevron-provided or user-defined — exposes a static
// getID() method. The ID is generated once on first call via a local static, making it
// stable for the process lifetime and consistent across translation units and shared
// libraries without any RTTI involvement.
// ===================================================================================== //

class DatabaseConnector {
public:
    // Required by the component contract.
    // Returns a unique integer ID for this type, generated once at program startup.
    static ComponentID getID() noexcept {
        static ComponentID id = ComponentRegistry::nextID();
        return id;
    }

    void query(std::string_view sql) { /* ... */ }
};


// ===================================================================================== //
// PART 2: How the store holds components
//
// Each entry pairs a destructor function pointer with a void* owning the component.
// No std::any, no std::type_index, no RTTI. The destructor is captured at registration
// time so the store can clean up correctly without knowing the concrete type later.
// The map is keyed on the stable integer ComponentID.
// ===================================================================================== //

class WindowComponentStore {
public:

    template <typename T, typename... Args>
    void add(Args&&... args) {
        ComponentID id = T::getID();

        // Construct the component on the heap, store it type-erased.
        Entry entry;
        entry.ptr      = new T(std::forward<Args>(args)...);
        entry.destruct = [](void* p) { delete static_cast<T*>(p); };

        components_[id] = std::move(entry);
    }

private:

    struct Entry {
        void*             ptr      = nullptr;
        void (*destruct)(void*)    = nullptr;
    };

    std::unordered_map<ComponentID, Entry> components_;


// ===================================================================================== //
// PART 3: How the store retrieves a component
//
// get<T>() calls T::getID() to find the integer key, looks it up in the map, and
// casts the void* back to T*. The cast is safe because add<T>() and get<T>() are
// both templated on the same T — the store never casts to the wrong type.
// Returns nullptr if the component was not registered.
// ===================================================================================== //

public:

    template <typename T>
    T* get() noexcept {
        auto it = components_.find(T::getID());
        if (it == components_.end()) {
            return nullptr;
        }
        return static_cast<T*>(it->second.ptr);
    }

    ~WindowComponentStore() {
        // Destroy all components using the captured destructor.
        // Each entry knows how to clean itself up without needing the concrete type.
        for (auto& [id, entry] : components_) {
            if (entry.ptr) {
                entry.destruct(entry.ptr);
            }
        }
    }
};


// ===================================================================================== //
// Usage — how these three parts work together at a call site
// ===================================================================================== //

// Registration (construction time, inside the factory callable or setup phase):
store.add<DatabaseConnector>(/* constructor args */);

// Retrieval (anywhere the store is accessible, e.g. through WindowContext):
DatabaseConnector* db = store.get<DatabaseConnector>();
if (db) {
    db->query("SELECT ...");
}
```

The key thing to observe is how the three parts stay decoupled. The component type knows only its own ID. The store knows only integer keys and opaque pointers. The `add`/`get` template pair is the only place where the concrete type is known — and they're always used symmetrically, so the cast is always safe.

