 ```cpp
// ===================================================================================== //
// Factory Callable — Conceptual User Perspective
//
// A factory callable is any callable with the correct signature that the user registers
// against a WindowFactory before committing their engine to AppProcess. It is the seam
// between Chevron's dispatch machinery and the user's window construction logic.
//
// Because the factory is any callable — not just a plain function — it can close over
// whatever application state the window needs at construction time. Chevron provides
// WindowInitContext for the things only Chevron can provide. Everything else is the
// factory author's domain.
// ===================================================================================== //


// -----------------------------------------------------------------------------
// Example 1: A stateless factory — simplest case
//
// A plain lambda with no captures. Appropriate when the window needs no external
// state to construct itself beyond what Chevron provides.
// -----------------------------------------------------------------------------

auto mainWindowFactory = [](chevron::WindowInitContext& ctx)
    -> std::unique_ptr<chevron::WindowEnvelope>
{
    // Construct the backend window using whatever the framework requires.
    // For a top-level window there is no parent handle — ctx.kind() confirms this.
    auto* frame = new MyMainWindow();

    // Deliver WindowContext to the window so it can access Chevron's per-window
    // capabilities from within its own event handlers and methods.
    // The window retains this for its lifetime.
    frame->attachContext(ctx.windowContext());

    // Hand the backend window handle and the init context to Chevron.
    // Chevron constructs the envelope, assigns identity, populates base components,
    // and returns ownership. The factory returns that ownership to the dispatcher.
    return chevron::make_envelope(frame, ctx);
};


// -----------------------------------------------------------------------------
// Example 2: A stateful factory — closed over application state
//
// A lambda that captures external state the window needs at construction time.
// The captured data travels into the factory through the closure — WindowInitContext
// carries none of it. This is the intended model for windows that need configuration,
// database handles, documents, or any other application-specific construction data.
// -----------------------------------------------------------------------------

AppConfig config = loadConfig();
auto documentSource = std::make_shared<DocumentSource>("index.html");

auto editorWindowFactory = [config, documentSource](chevron::WindowInitContext& ctx)
    -> std::unique_ptr<chevron::WindowEnvelope>
{
    // The window receives both Chevron-provided context and user-provided state.
    // WindowContext is delivered via the constructor here — an alternative to
    // the setter approach shown in Example 1. Either path is valid; the choice
    // depends on whether the framework base class allows a flexible constructor.
    auto* frame = new EditorWindow(ctx.windowContext(), config, documentSource);

    return chevron::make_envelope(frame, ctx);
};


// -----------------------------------------------------------------------------
// Example 3: A stateful factory for a subsidiary window
//
// Subsidiary windows are dispatched with a declared parent. WindowInitContext
// carries the parent handle — the one piece of Chevron-managed information the
// factory genuinely cannot obtain any other way. The factory casts it to the
// appropriate framework type and passes it to the backend window constructor.
// -----------------------------------------------------------------------------

auto inspectorPanelFactory = [](chevron::WindowInitContext& ctx)
    -> std::unique_ptr<chevron::WindowEnvelope>
{
    // Retrieve the parent window handle for subsidiary window construction.
    // The cast is safe — the factory author knows which framework is in use.
    auto* parent = ctx.getParentAs<MyMainWindow>();

    auto* panel = new InspectorPanel(parent, ctx.windowContext());

    return chevron::make_envelope(panel, ctx);
};


// -----------------------------------------------------------------------------
// Example 4: A functor factory — when the factory itself needs to be stateful
// across multiple dispatches
//
// A functor class is appropriate when the factory needs to maintain state between
// invocations — for example, tracking how many instances it has produced, or
// holding a resource that is expensive to construct and should be shared across
// all windows this factory produces.
// -----------------------------------------------------------------------------

class DocumentWindowFactory {
public:
    explicit DocumentWindowFactory(DocumentLibrary& library)
        : library_(library)
    {}

    std::unique_ptr<chevron::WindowEnvelope> operator()(chevron::WindowInitContext& ctx)
    {
        // State carried in the functor — available on every dispatch invocation.
        auto document = library_.openNext();
        instanceCount_++;

        auto* frame = new DocumentWindow(ctx.windowContext(), std::move(document));
        return chevron::make_envelope(frame, ctx);
    }

private:
    DocumentLibrary& library_;
    int              instanceCount_ = 0;
};

// Registration — the functor is submitted as the factory callable.
// Chevron stores it; the library_ reference and instanceCount_ persist
// across every dispatch invocation of this factory.
engine.windowing().registerFactory(
    DocumentWindowFactory { documentLibrary },
    chevron::FactoryDescriptor::none()
);
```

