 ```cpp
// ===================================================================================== //
// Path 1: Using the Chevron-provided base type
//
// The user subclasses chevron::wx::Window instead of wxFrame directly.
// chevron::wx::Window is wxFrame — it is publicly additive only. The user
// retains full access to the entire wxWidgets API surface. What they gain
// is infrastructure registration helpers like attachViewport() that handle
// the WindowContext registration ceremony automatically.
// ===================================================================================== //

class EditorWindow : public chevron::wx::Window {
public:

    EditorWindow(chevron::WindowContext ctx)
        : chevron::wx::Window(nullptr, wxID_ANY, "Editor")
        , context_(std::move(ctx))
    {
        // attachViewport() is provided by chevron::wx::Window.
        // It constructs the Viewport, registers it with the logical view
        // layer through WindowContext, and returns a handle to it.
        // No manual WindowContext interaction required.
        auto& main = attachViewport("main");
        main.addPage<DocumentPage>();
        main.addPage<PreviewPage>();

        auto& tools = attachViewport("tools");
        tools.addPage<PropertiesPage>();
        tools.addPage<OutlinePage>();
    }

    // Everything beyond this point is completely normal wxWidgets code.
    // Chevron is present only through WindowContext and the Viewport/Page
    // types the user has already attached. No further ceremony required.

    void onSaveDocument(wxCommandEvent&) {
        context_.logger().info("Saving document");
        // ... normal wxWidgets work
    }

    void onOpenSettings(wxCommandEvent&) {
        // Navigate within the tools viewport through WindowContext.
        context_.viewport("tools").navigateTo<PropertiesPage>();
    }

private:
    chevron::WindowContext context_;
};


// ===================================================================================== //
// Path 2: Without the Chevron-provided base type
//
// The user subclasses wxFrame directly — no Chevron type in the inheritance
// chain at all. Viewport and Page registration is performed manually through
// WindowContext. This path is fully supported and equally correct.
// The user assumes the registration ceremony themselves.
// ===================================================================================== //

class EditorWindow : public wxFrame {
public:

    EditorWindow(chevron::WindowContext ctx)
        : wxFrame(nullptr, wxID_ANY, "Editor")
        , context_(std::move(ctx))
    {
        // Viewport and Page construction and registration are explicit here.
        // The user calls into WindowContext directly to register each viewport.
        auto& main = context_.registerViewport<chevron::wx::Viewport>("main");
        main.addPage<DocumentPage>();
        main.addPage<PreviewPage>();

        auto& tools = context_.registerViewport<chevron::wx::Viewport>("tools");
        tools.addPage<PropertiesPage>();
        tools.addPage<OutlinePage>();
    }

    // From this point on the two paths are identical in character.
    // WindowContext is the same, navigation is the same, Chevron
    // capabilities are accessed the same way. Only the registration
    // ceremony above differed.

    void onSaveDocument(wxCommandEvent&) {
        context_.logger().info("Saving document");
    }

    void onOpenSettings(wxCommandEvent&) {
        context_.viewport("tools").navigateTo<PropertiesPage>();
    }

private:
    chevron::WindowContext context_;
};
```

The thing I want to draw your attention to is how the two paths converge the moment construction is done. The event handlers are identical — `context_.logger()`, `context_.viewport()`, `navigateTo()` — because `WindowContext` is the same object in both cases. The only thing that differed was whether `attachViewport()` handled the registration or the user called `context_.registerViewport()` themselves. That's the entire practical difference between the two paths from the user's perspective.

